window.QSBI_LESSONS=window.QSBI_LESSONS||{};QSBI_LESSONS[4]=[{"id":"04_19","g":4,"l":19,"topic":"Права покупателя: чек, обмен и возврат","module":"Коммуникации и продажи","format":"Комбинированный","skills":["Работа с клиентом","Переговоры","Критическое мышление"],"goal":"К концу урока ученик сможет назвать 3 права покупателя — на информацию о товаре, на качественный товар, на обмен или возврат — и вежливо разыграть возврат товара по чеку.","criteria":["Я называю 3 права покупателя.","Я объясняю, зачем хранить чек.","Я вежливо разыгрываю возврат или обмен, как покупатель и как продавец."],"result":"Сценка «Возврат товара по чеку» в паре (покупатель — продавец) и памятка «3 права покупателя».","stages":[{"stage":"Разминка «Найди пару»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"match","name":"Найди пару","rules":["На экране определения под номерами.","Учитель называет слово, например: «Слово А — …». 10 секунд на поиск.","Все одновременно показывают номер подходящего определения на пальцах."],"items":[{"term":"Покупатель (customer)","real":"Человек, который покупает товар или услугу","shown":"Человек, который покупает товар или услугу","truth":true,"first":"П"},{"term":"Чек","real":"Бумага или электронный документ, который подтверждает покупку: что купили, когда и за сколько","shown":"Общение, обмен информацией между людьми","truth":false,"first":"Ч"},{"term":"Обмен","real":"Когда товар меняют на другой такой же или похожий","shown":"Когда товар меняют на другой такой же или похожий","truth":true,"first":"О"},{"term":"Возврат","real":"Когда покупатель отдаёт товар и получает деньги обратно","shown":"Бумага или электронный документ, который подтверждает покупку: что купили, когда и за сколько","truth":false,"first":"В"},{"term":"Брак","real":"Дефект, поломка товара, которая была при покупке","shown":"Дефект, поломка товара, которая была при покупке","truth":true,"first":"Б"},{"term":"Коммуникация (communication)","real":"Общение, обмен информацией между людьми","shown":"Когда покупатель отдаёт товар и получает деньги обратно","truth":false,"first":"К"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Покупатель (customer)","def":"Человек, который покупает товар или услугу"},{"term":"Чек","def":"Бумага или электронный документ, который подтверждает покупку: что купили, когда и за сколько"},{"term":"Обмен","def":"Когда товар меняют на другой такой же или похожий"},{"term":"Возврат","def":"Когда покупатель отдаёт товар и получает деньги обратно"},{"term":"Брак","def":"Дефект, поломка товара, которая была при покупке"},{"term":"Коммуникация (communication)","def":"Общение, обмен информацией между людьми"},{"term":"Права потребителя","def":"То, что закон гарантирует каждому покупателю"}],"english":"customer — покупатель; communication — коммуникация","concepts":{"head":"Понятия","items":["Права потребителя защищает закон: в Казахстане действует Закон «О защите прав потребителей».","Чек — доказательство покупки.","Обмен — на другой товар.","Возврат — деньги назад.","Брак — дефект с самого начала.","Коммуникация (communication) — вежливый разговор продавца и покупателя (customer)."]},"scheme":"Три щита: «Информация», «Качество», «Обмен и возврат». Ниже дорожка из 6 шагов возврата, в начале — значок чека.","examples":[{"lab":"Казахстан","text":"Айгерим купила наушники за 6500 тенге, через 3 дня один наушник перестал работать — это брак. С чеком она вернула наушники и получила 6500 тенге."},{"lab":"Мир","text":"В Европе многие интернет-магазины дают 14 дней, чтобы вернуть покупку, сделанную онлайн."}],"mistake":{"myth":"Покупатель кричит и требует, а продавец спорит","fix":"Показать сценку «плохо» и «хорошо»; правило — спокойный тон, факты, чек."},"check":[{"q":"Зачем хранить чек?","a":"Он доказывает, где, когда и за сколько куплен товар"},{"q":"Наушники с браком — что можно потребовать?","a":"Замену, ремонт или деньги"},{"q":"Как начать разговор о возврате?","a":"«Здравствуйте, я купил… и у него проблема…»"}],"kz":{"text":"В Казахстане действует Закон «О защите прав потребителей», а жаловаться на нарушения можно в государственный орган по защите прав потребителей.","link":"закон защищает и взрослых, и детей-покупателей."},"world":{"text":"15 марта во многих странах отмечают Всемирный день прав потребителей. Он напоминает, что каждый покупатель в мире имеет право на безопасный и качественный товар и честную информацию.","link":""},"fact":"Всемирный день прав потребителей отмечают 15 марта: в этот день в 1962 году президент США Джон Кеннеди выступил с речью о правах потребителей, назвав право на безопасность, информацию, выбор и право быть услышанным.","cards":[{"n":"1","title":"Можно вернуть или обменять?","lines":["1) Куртка не подошла по размеру, ярлыки и чек есть, прошло 5 дней. (Можно обменять.)","2) Наушники за 6500 тенге сломались через 3 дня сами, чек есть. (Брак — замена или возврат 6500 тенге.)","3) Мяч порвался, потому что его пинали об забор, прошёл месяц. (Нельзя: испорчен покупателем.)","4) На упаковке сока не написан срок годности. (Нарушено право на информацию.)"],"hand":"Сдать: ответы.","answers":[]},{"n":"2","title":"Сценка «Возврат по чеку»","lines":["Покупатель: «Здравствуйте! Я купил(а) … (дата). У товара проблема: … . Вот чек.»","Продавец: «Здравствуйте! Давайте посмотрим. Да, это брак. Хотите обмен или вернуть деньги?»","Покупатель: «Я хочу …»","Продавец: «Хорошо. Возвращаю … тенге / вот новый товар. Извините за неудобство.»","Оба: «Спасибо! До свидания!»","Чек: магазин «Дала», дата __, наушники — 6500 тенге."],"hand":"Сдать: сценку (показ).","answers":[]}],"practice":[{"type":"scene","title":"Сломанная машинка","minutes":7,"setting":"Магазин игрушек «Весёлый кубик». Вчера здесь купили машинку на пульте, а сегодня у неё отвалилось колесо.","roles":[{"name":"Покупатель","task":"Купил машинку вчера. Чек у тебя в кармане. Говоришь вежливо, но твёрдо."},{"name":"Ребёнок покупателя","task":"Очень расстроен, хочет новую машинку прямо сейчас."},{"name":"Продавец-новичок","task":"Первый день на работе. Сначала говоришь: «Возврата нет!»"},{"name":"Старший продавец","task":"Знаешь правила магазина. Приходишь, когда начинается спор, и решаешь, как правильно."}],"steps":["Покупатели входят и показывают сломанную машинку.","Продавец-новичок отказывает: «Возврата нет!»","Покупатель спокойно говорит о своём праве и показывает чек.","Старший продавец предлагает: обменять на новую или вернуть деньги."],"freeze":["Стоп-кадр! Кто сейчас прав и почему?","Что покупатель правильно взял с собой в магазин?"],"twist":"Поворот: чек потерялся! Как теперь покупателю доказать, что машинку купили здесь?","debrief":["Какие права есть у покупателя?","Почему спокойный разговор работает лучше крика?","Зачем хранить чек хотя бы до конца проверки товара?"]},{"type":"scene","title":"Не тот размер","minutes":6,"setting":"Обувной магазин. Кроссовки купили в подарок, но они малы. Их ни разу не надевали.","roles":[{"name":"Покупатель","task":"Принёс кроссовки в коробке, бирки на месте. Хочешь обменять на размер больше."},{"name":"Продавец","task":"Сначала проверяешь: товар новый? бирки есть? чек есть? Потом помогаешь."},{"name":"Ещё один покупатель","task":"Стоишь в очереди и торопишь: «Побыстрее!»"}],"steps":["Покупатель объясняет, что размер не подошёл.","Продавец задаёт три вопроса-проверки.","Продавец предлагает обмен."],"freeze":["Стоп-кадр! Какие три вещи проверил продавец?","Можно ли обменять обувь, которую уже носили на улице?"],"twist":"Поворот: оказывается, бирку оторвали дома. Что скажет продавец?","debrief":["Чем обмен отличается от возврата?","Почему продавец проверяет, носили ли товар?"]},{"type":"scene","title":"Возврат по-честному","minutes":5,"setting":"Покупатель хочет вернуть игрушку, которая просто разонравилась, а не сломалась.","roles":[{"name":"Покупатель","task":"Говоришь: «Мне просто разонравилось»."},{"name":"Продавец","task":"Объясняешь правила магазина спокойно."},{"name":"Мама покупателя","task":"Помогаешь понять, что честно."}],"steps":["Покупатель просит вернуть деньги.","Продавец объясняет правила.","Мама помогает найти решение."],"freeze":["Стоп-кадр! Честно ли требовать возврат, если товар хороший?"],"twist":"Поворот: магазин сам предлагает обмен на другую игрушку. Это хорошее решение?","debrief":["Когда можно вернуть товар, а когда нельзя?"]}],"homework":"Найти дома один чек (бумажный или в приложении) и с родителями найти на нём: магазин, дату, товар и цену.","support":"Сценарий с готовыми репликами и картинка-чек с подписями частей.","advanced":"Разобрать ситуацию, где возврат невозможен (товар испорчен покупателем), и придумать, как вежливо отказать как продавец.","photo":{"src":"lessons/img/04_19.jpg","author":"Simon Kadula","q":["Что вы видите на фото? Как это связано с нашей темой?","Какое право покупателя кажется вам самым важным и почему?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g04-l19.pptx","name":"19. Права покупателя — чек, обмен и возврат (4 кл).pptx","mb":1.3}},{"id":"04_20","g":4,"l":20,"topic":"Виды продаж","module":"Коммуникации и продажи","format":"Тренинг навыка","skills":["Работа с клиентом","Критическое мышление","Переговоры"],"goal":"К концу урока ученик сможет различить продажу в магазине, онлайн и на ярмарке по 3 признакам, привести пример каждой и провести в паре короткую продажу по классической схеме в одном из видов.","criteria":["Я называю 3 вида продаж и привожу пример каждого.","Я объясняю, чем они отличаются: где встречаются продавец и покупатель, как платят, как получают товар.","Я провожу мини-продажу по схеме."],"result":"Таблица «3 вида продаж» с примерами и мини-продажа в паре (магазин, онлайн-чат или ярмарка) по схеме «приветствие — вопрос — предложение — покупка — спасибо».","stages":[{"stage":"Разминка «Правда или ловушка?»","min":5},{"stage":"Показ навыка","min":6},{"stage":"Отработка в парах","min":12},{"stage":"Обратная связь","min":7},{"stage":"Повторная попытка","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"truth","name":"Правда или ловушка?","rules":["Учитель читает слово урока и объяснение — правильное или «перепутанное».","10 секунд молча решаем, так ли объясняется слово.","«Три-два-один!» — все сразу показывают: ладонь вверх = ПРАВДА, кулак = ЛОВУШКА."],"items":[{"term":"Продажи (sales)","real":"Обмен товара или услуги на деньги","shown":"Обмен товара или услуги на деньги","truth":true,"first":"П"},{"term":"Коммуникация (communication)","real":"Общение продавца и покупателя","shown":"Все виды товаров у продавца","truth":false,"first":"К"},{"term":"Продажа в магазине","real":"Покупатель приходит сам, видит и трогает товар","shown":"Покупатель приходит сам, видит и трогает товар","truth":true,"first":"П"},{"term":"Онлайн-продажа","real":"Покупка через сайт или приложение, товар привозят или забирают в пункте выдачи","shown":"Общение продавца и покупателя","truth":false,"first":"О"},{"term":"Продажа на ярмарке","real":"Временный рынок, где продавец сам привлекает покупателей","shown":"Временный рынок, где продавец сам привлекает покупателей","truth":true,"first":"П"},{"term":"Ассортимент","real":"Все виды товаров у продавца","shown":"Покупка через сайт или приложение, товар привозят или забирают в пункте выдачи","truth":false,"first":"А"}],"perm":[1,0,5,4,3,2]},"glossary":[{"term":"Продажи (sales)","def":"Обмен товара или услуги на деньги"},{"term":"Коммуникация (communication)","def":"Общение продавца и покупателя"},{"term":"Продажа в магазине","def":"Покупатель приходит сам, видит и трогает товар"},{"term":"Онлайн-продажа","def":"Покупка через сайт или приложение, товар привозят или забирают в пункте выдачи"},{"term":"Продажа на ярмарке","def":"Временный рынок, где продавец сам привлекает покупателей"},{"term":"Ассортимент","def":"Все виды товаров у продавца"},{"term":"Активная продажа","def":"Продавец сам ищет и приглашает покупателя"}],"english":"sales — продажи; communication — коммуникация","concepts":{"head":"Понятия","items":["Продажи (sales) — обмен товара на деньги.","Активная продажа — продавец сам ищет покупателя (ярмарка, звонок, предложение).","Пассивная — покупатель приходит сам (магазин, сайт).","Ассортимент — набор товаров."]},"steps":{"head":"Как различать, по 3 признакам","items":["Признак 1 — где встречаются: в магазине лицом к лицу; онлайн — через экран; на ярмарке — на улице, временно","Признак 2 — как платят: на кассе; картой или переводом в приложении; наличными или переводом у прилавка","Признак 3 — как получают товар: сразу; доставкой через 1–3 дня; сразу у прилавка","Классическая схема продажи: приветствие → вопрос о потребности → предложение → ответ на сомнения → покупка → благодарность"]},"scheme":"Таблица 3 × 3: столбцы «Магазин | Онлайн | Ярмарка», строки «Где встречаются | Как платят | Как получают». Под таблицей — стрелка классической схемы из 6 шагов.","examples":[{"lab":"Казахстан","text":"Супермаркет Magnum — продажа в магазине; Kaspi.kz — онлайн-продажи с доставкой; Зелёный базар и праздничные ярмарки — продажа на рынке."},{"lab":"Расчёт","text":"Книга в магазине — 3200 тенге; онлайн — 2900 тенге + доставка 500 тенге = 3400 тенге; на ярмарке — 3000 тенге. Где дешевле? На ярмарке."},{"lab":"Мир","text":"Amazon в США начинал как онлайн-магазин книг."}],"mistake":{"myth":"«Онлайн всегда дешевле»","fix":"Сложить цену и доставку и сравнить; иногда в магазине выгоднее."},"check":[{"q":"Чем онлайн-продажа отличается от магазина?","a":"Покупатель не трогает товар, получает его позже"},{"q":"Почему на ярмарке продажа активная?","a":"Продавец сам зовёт покупателей"},{"q":"2900 + 500 = ?","a":"3400 тенге"}],"kz":{"text":"Kaspi.kz — казахстанская компания, через приложение которой люди покупают товары онлайн, а магазины Magnum и базары продают вживую.","link":"в Казахстане работают все три вида продаж, и многие продавцы используют сразу несколько."},"world":{"text":"Компания Amazon начала в 1994 году в США как интернет-магазин книг, а сейчас продаёт миллионы товаров по всему миру. Но и сегодня во многих странах люди любят рынки и ярмарки, где можно поговорить с продавцом.","link":""},"fact":"Компанию Amazon основал Джефф Безос в 1994 году; сначала она продавала только книги через интернет, а первые заказы упаковывали в гараже.","cards":[{"n":"1","title":"Три вида продаж (sales)","lines":["Заполни таблицу:","Где встречаются: магазин ___ / онлайн ___ / ярмарка ___","Как платят: магазин ___ / онлайн ___ / ярмарка ___","Как получают товар: магазин ___ / онлайн ___ / ярмарка ___","Пример каждого вида из Казахстана: ___ / ___ / ___","Задача: книга в магазине 3200 тенге; онлайн 2900 + доставка 500; на ярмарке 3000. Где дешевле?"],"hand":"Сдать: таблицу.","answers":[["","На ярмарке, 3000 тенге; онлайн выходит 3400."]]},{"n":"2","title":"Мини-продажа (вытяни вид)","lines":["Магазин: покупатель ищет подарок другу 10 лет.","Онлайн-чат: покупатель пишет «Есть ли рюкзак синего цвета?»","Ярмарка: покупатель проходит мимо прилавка с закладками.","Схема: 1) приветствие; 2) вопрос «Что вам нужно?»; 3) предложение; 4) ответ на сомнение; 5) покупка и чек; 6) «Спасибо за покупку!»"],"hand":"Сдать: проведённую продажу.","answers":[]}],"practice":[{"type":"scene","title":"Одна игрушка — три магазина","minutes":8,"setting":"Класс превращается в три точки продаж одной и той же игрушки: обычный магазин, интернет-магазин и ярмарка.","roles":[{"name":"Продавец в магазине","task":"Стоишь за прилавком, даёшь потрогать игрушку, рассказываешь о ней."},{"name":"Продавец интернет-магазина","task":"Ты «за экраном»: держишь перед лицом рамку из рук. Покупатель не может потрогать товар — описывай его словами и «фото»."},{"name":"Продавец на ярмарке","task":"Громко зазываешь, предлагаешь скидку прямо сейчас."},{"name":"Покупатель","task":"Обходишь все три места и выбираешь, где купить. Объясняешь выбор."}],"steps":["Покупатель заходит в обычный магазин.","Потом «открывает» интернет-магазин.","Потом идёт на ярмарку.","Покупатель выбирает и объясняет почему."],"freeze":["Стоп-кадр! Где можно потрогать товар до покупки?","Где покупка быстрее всего? А где можно поторговаться?"],"twist":"Поворот: в интернет-магазине доставка завтра, а подарок нужен сегодня. Изменится ли выбор?","debrief":["Какие три вида продаж мы показали?","Чем удобен каждый для покупателя? А для продавца?"]},{"type":"scene","title":"Звонок бабушке","minutes":6,"setting":"Продажа по телефону. Оператор звонит бабушке и предлагает подписку на детский журнал для внука.","roles":[{"name":"Оператор","task":"Говоришь вежливо и коротко. Спрашиваешь, удобно ли говорить."},{"name":"Бабушка","task":"Плохо слышишь и не понимаешь сложных слов вроде «подписка» и «промокод»."},{"name":"Внук","task":"Стоишь рядом с бабушкой и подсказываешь ей."}],"steps":["Оператор здоровается и спрашивает, удобно ли говорить.","Объясняет предложение простыми словами.","Бабушка задаёт вопросы.","Оператор отвечает и вежливо прощается — даже если бабушка отказалась."],"freeze":["Стоп-кадр! Какое слово бабушка не поняла? Как сказать проще?"],"twist":"Поворот: бабушка говорит: «Перезвоните, когда внук будет дома». Что ответит оператор?","debrief":["Чем продажа по телефону отличается от продажи в магазине?","Почему важно спросить, удобно ли говорить?"]},{"type":"scene","title":"Покупка в автомате","minutes":5,"setting":"Ученик покупает сок в торговом автомате, а автомат «съел» монету.","roles":[{"name":"Покупатель","task":"Опускаешь монету, сок не выпал."},{"name":"Автомат","task":"Молчишь и мигаешь лампочкой."},{"name":"Владелец автомата","task":"Приходишь по номеру телефона на наклейке."}],"steps":["Покупатель покупает.","Автомат не выдаёт сок.","Покупатель звонит владельцу."],"freeze":["Стоп-кадр! Кто здесь продавец, если продавца нет?"],"twist":null,"debrief":["Какие ещё бывают продажи без продавца?"]}],"homework":"Сравнить с родителями цену одного товара в магазине и в интернете (с доставкой) и записать, где выгоднее.","support":"Таблица с подсказками-картинками и сценарий мини-продажи с готовыми фразами.","advanced":"Придумать, как продавец ярмарки может продавать ещё и онлайн, и какие 2 вещи ему для этого нужны.","photo":{"src":"lessons/img/04_20.jpg","author":"Jonathan Borba","q":["Что вы видите на фото? Как это связано с нашей темой?","Что можно купить только вживую, а что удобнее онлайн?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g04-l20.pptx","name":"20. Виды продаж (4 кл).pptx","mb":1.7}},{"id":"04_21","g":4,"l":21,"topic":"Продажи как технология: этапы и техники","module":"Коммуникации и продажи","format":"Тренинг навыка","skills":["Работа с клиентом","Переговоры","Критическое мышление"],"goal":"К концу урока ученик сможет назвать 5 этапов продажи и разыграть их в паре, задав покупателю 3 вида вопросов — о ситуации, о проблеме и о пользе.","criteria":["Я называю 5 этапов продажи по порядку.","Я задаю вопросы о ситуации, проблеме и пользе, а не навязываю товар.","Я провожу все этапы в сценке и улучшаю их после обратной связи."],"result":"Сценка продажи в паре по 5 этапам с картой вопросов «Ситуация — Проблема — Польза» и отметками партнёра.","stages":[{"stage":"Разминка «Угадай слово»","min":5},{"stage":"Показ навыка","min":6},{"stage":"Отработка в парах","min":12},{"stage":"Обратная связь","min":7},{"stage":"Повторная попытка","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"guess","name":"Угадай слово","rules":["Слово спрятано — звучит только его объяснение и первая буква.","10 секунд команда шёпотом выбирает одно слово.","«Три-два-один!» — все команды хором называют слово. Верно — балл команде."],"items":[{"term":"Продажи (sales)","real":"Обмен товара или услуги на деньги, когда товар помогает покупателю","shown":"Обмен товара или услуги на деньги, когда товар помогает покупателю","truth":true,"first":"П"},{"term":"Коммуникация (communication)","real":"Общение и обмен информацией","shown":"Человек, который покупает","truth":false,"first":"К"},{"term":"Этапы продажи","real":"Шаги, по которым продавец ведёт разговор с покупателем","shown":"Шаги, по которым продавец ведёт разговор с покупателем","truth":true,"first":"Э"},{"term":"Техника вопросов","real":"Продавец задаёт вопросы, чтобы понять, что нужно покупателю","shown":"Общение и обмен информацией","truth":false,"first":"Т"},{"term":"Потребность","real":"То, что нужно покупателю","shown":"То, что нужно покупателю","truth":true,"first":"П"},{"term":"Клиент","real":"Человек, который покупает","shown":"Продавец задаёт вопросы, чтобы понять, что нужно покупателю","truth":false,"first":"К"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Продажи (sales)","def":"Обмен товара или услуги на деньги, когда товар помогает покупателю"},{"term":"Коммуникация (communication)","def":"Общение и обмен информацией"},{"term":"Этапы продажи","def":"Шаги, по которым продавец ведёт разговор с покупателем"},{"term":"Техника вопросов","def":"Продавец задаёт вопросы, чтобы понять, что нужно покупателю"},{"term":"Потребность","def":"То, что нужно покупателю"},{"term":"Клиент","def":"Человек, который покупает"},{"term":"Стартапер","def":"Человек, который начинает новый бизнес"}],"english":"sales — продажи; communication — коммуникация","concepts":{"head":"Понятия","items":["Продажа (sales) как технология — разговор по шагам.","Хороший продавец не навязывает товар, а помогает выбрать.","Техника вопросов (упрощённая идея известной методики продаж через вопросы) — сначала узнать, потом предложить."]},"steps":{"head":"5 этапов, по шагам","items":["Этап 1 — контакт: улыбка, приветствие, имя","Этап 2 — вопросы: о ситуации («Для чего вам?»), о проблеме («Что не нравится в старом?»), о пользе («Что будет, если это решить?»)","Этап 3 — предложение: товар + польза для этого клиента","Этап 4 — ответ на сомнения: спокойно, с фактом","Этап 5 — завершение: покупка, чек, «спасибо», приглашение прийти ещё","Нельзя пугать покупателя, давить и обманывать — это нечестные приёмы"]},"scheme":"Лестница из 5 ступеней: «Контакт → Вопросы (С, П, П) → Предложение → Сомнения → Завершение». Сбоку красный знак «Нельзя: пугать, давить, обманывать».","examples":[{"lab":"Казахстан","text":"В спортивном магазине в Караганде продавец спрашивает: «Для чего вам кроссовки?» — «Для бега в парке». — «Что неудобно в старых?» — «Натирают». — «Будет ли удобнее бегать дольше?» — «Да». Предложение: беговые кроссовки за 18 000 тенге. Если 8 покупателей из 10 после таких вопросов выбирают товар без возврата — техника работает."},{"lab":"Мир","text":"В компаниях многих стран продавцов учат слушать больше, чем говорить."}],"mistake":{"myth":"Продавец сразу рассказывает обо всех товарах, не задав ни одного вопроса","fix":"Сценка «без вопросов» и «с вопросами» — сравнить, какой покупатель довольнее."},"check":[{"q":"Какой этап первый?","a":"Контакт"},{"q":"Зачем вопросы до предложения?","a":"Чтобы понять потребность"},{"q":"«Купите, иначе пожалеете!» — честно?","a":"Нет, это давление и запугивание"}],"kz":{"text":"Спортивные магазины в Казахстане, например в торговых центрах Астаны и Алматы, часто подбирают обувь по вопросам: для чего, как часто, где бегаете.","link":"вопросы помогают продать подходящий товар и избежать возвратов."},"world":{"text":"Во многих странах исследования продаж показали: успешные продавцы задают больше вопросов и внимательнее слушают клиента. Поэтому компании учат продавцов не уговаривать, а помогать выбрать.","link":""},"fact":"Методику продаж через вопросы (СПИН) описал британский исследователь Нил Рекхэм в книге 1988 года после изучения тысяч реальных продажных встреч.","cards":[{"n":"1","title":"Карта вопросов","lines":["Товары: кроссовки (18 000 тенге), рюкзак (9 500 тенге), настольная игра (6 000 тенге), термос (4 500 тенге).","Ситуация: «Для чего вам…?», «Где будете пользоваться?»","Проблема: «Что неудобно в старом?», «Что мешает?»","Польза: «Что изменится, если…?», «Будет ли удобнее…?»","Нельзя: пугать («пожалеете!»), давить («берите быстрее!»), обманывать."],"hand":"Сдать: свои 3 вопроса для выбранного товара.","answers":[]},{"n":"2","title":"Чек-лист покупателя","lines":["Контакт (приветствие) — да / нет","Вопрос о ситуации — да / нет","Вопрос о проблеме — да / нет","Вопрос о пользе — да / нет","Предложение с пользой для меня — да / нет","Ответ на сомнение — да / нет","Завершение и «спасибо» — да / нет","Совет продавцу: ____"],"hand":"Сдать: чек-лист партнёру.","answers":[]}],"practice":[{"type":"scene","title":"Продай мне рюкзак","minutes":8,"setting":"Магазин школьных товаров. Продавец проходит все 5 этапов продажи, а класс следит, не пропустил ли он этап.","roles":[{"name":"Продавец","task":"Проходишь этапы по порядку: приветствие → вопросы → рассказ о товаре → ответ на возражение → завершение."},{"name":"Покупатель","task":"Хочешь рюкзак, но сначала сомневаешься. На этапе 4 говоришь: «Дорого!»"},{"name":"Пять наблюдателей","task":"У каждого карточка с одним этапом. Поднимаешь её, когда продавец прошёл твой этап."}],"steps":["Приветствие: продавец здоровается и улыбается.","Вопросы: «Для чего вам рюкзак? Что для вас важно?»","Рассказ о товаре: только о том, что важно покупателю.","Возражение «Дорого!» — продавец спокойно отвечает.","Завершение: «Берёте? Пробить на кассе?»"],"freeze":["Стоп-кадр! Какую карточку ещё никто не поднял?","Что продавец узнал из вопросов?"],"twist":"Поворот: покупатель говорит «Я подумаю» и идёт к выходу. Что делает продавец?","debrief":["Какой этап был самым трудным?","Почему вопросы задают ДО рассказа о товаре?"]},{"type":"scene","title":"Торопыга и Слушатель","minutes":6,"setting":"Два продавца продают один и тот же товар — пенал. Покупатель один.","roles":[{"name":"Продавец-торопыга","task":"Сразу рассказываешь всё о пенале и не задаёшь ни одного вопроса."},{"name":"Продавец-слушатель","task":"Сначала задаёшь 2 вопроса, потом рассказываешь только нужное."},{"name":"Покупатель","task":"Ищешь пенал, куда влезет линейка 30 см. Покупаешь у того, кто тебя понял."}],"steps":["Покупатель подходит к торопыге.","Потом к слушателю.","Покупатель выбирает и объясняет."],"freeze":["Стоп-кадр! Узнал ли торопыга, что нужно покупателю?"],"twist":"Поворот: у слушателя пенал дороже. Купят ли у него всё равно?","debrief":["Почему слушатель продал лучше?","Какие два вопроса стоит задать любому покупателю?"]},{"type":"scene","title":"Этапы наоборот","minutes":5,"setting":"Продавец перепутал этапы: сразу говорит «Берёте?», не поздоровавшись.","roles":[{"name":"Продавец-путаник","task":"Начинаешь с конца: «Берёте? Платите!»"},{"name":"Покупатель","task":"Удивляешься и уходишь."},{"name":"Класс-режиссёры","task":"Говорите, в каком порядке надо."}],"steps":["Продавец путает этапы.","Покупатель уходит.","Класс исправляет порядок, продавец пробует снова."],"freeze":["Стоп-кадр! Какой этап был первым? Каким должен быть?"],"twist":null,"debrief":["Почему у продажи есть порядок этапов?"]}],"homework":"Попробовать дома «продать» родителям идею (например, совместную прогулку) по 5 этапам с 3 вопросами и записать, что сработало.","support":"Карта вопросов с готовыми формулировками для каждого вида и сценарий с пропусками.","advanced":"Придумать по 2 вопроса каждого вида для трёх разных товаров и показать сценку без подсказок.","photo":{"src":"lessons/img/04_21.jpg","author":"Blake Wisz","q":["Что вы видите на фото? Как это связано с нашей темой?","Какой продавец вам больше нравится — который много говорит или который слушает?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g04-l21.pptx","name":"21. Продажи как технология — этапы и техники (4 кл).pptx","mb":1.6}},{"id":"04_22","g":4,"l":22,"topic":"Продавец в мире профессий","module":"Коммуникации и продажи","format":"Комбинированный","skills":["Работа с клиентом","Критическое мышление","Переговоры"],"goal":"К концу урока ученик сможет назвать 3 качества хорошего продавца и в игре «Продавец» выяснить 3 вопросами, что нужно покупателю.","criteria":["Я называю 3 качества хорошего продавца и объясняю, зачем они нужны.","Я задаю 3 вопроса, чтобы узнать, что нужно покупателю.","Я предлагаю товар, который подходит под ответы покупателя."],"result":"«Паспорт профессии продавца» (обязанности и 3 качества) и результат игры «Продавец»: записанная потребность покупателя и предложенный товар.","stages":[{"stage":"Разминка «Найди пару»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"match","name":"Найди пару","rules":["На экране определения под номерами.","Учитель называет слово, например: «Слово А — …». 10 секунд на поиск.","Все одновременно показывают номер подходящего определения на пальцах."],"items":[{"term":"Продавец (seller)","real":"Человек, который помогает покупателю выбрать товар и продаёт его","shown":"Человек, который помогает покупателю выбрать товар и продаёт его","truth":true,"first":"П"},{"term":"Профессия (job)","real":"Работа, которой человек учится и занимается","shown":"То, что нужно клиенту","truth":false,"first":"П"},{"term":"Продажа","real":"Обмен товара на деньги, когда товар решает потребность клиента","shown":"Обмен товара на деньги, когда товар решает потребность клиента","truth":true,"first":"П"},{"term":"Ассортимент","real":"Все виды товаров у продавца","shown":"Работа, которой человек учится и занимается","truth":false,"first":"А"},{"term":"Клиент","real":"Человек, который покупает","shown":"Человек, который покупает","truth":true,"first":"К"},{"term":"Потребность","real":"То, что нужно клиенту","shown":"Все виды товаров у продавца","truth":false,"first":"П"}],"perm":[3,2,1,0,5,4]},"glossary":[{"term":"Продавец (seller)","def":"Человек, который помогает покупателю выбрать товар и продаёт его"},{"term":"Профессия (job)","def":"Работа, которой человек учится и занимается"},{"term":"Продажа","def":"Обмен товара на деньги, когда товар решает потребность клиента"},{"term":"Ассортимент","def":"Все виды товаров у продавца"},{"term":"Клиент","def":"Человек, который покупает"},{"term":"Потребность","def":"То, что нужно клиенту"},{"term":"Вежливость","def":"Уважительное поведение и слова"}],"english":"seller — продавец; job — профессия","concepts":{"head":"Понятия","items":["Продавец (seller) — профессия (job), в которой важно понимать людей.","От продавца часто зависит, захочет ли клиент купить.","Ассортимент — товары, которые продавец должен знать.","Потребность — что нужно клиенту."]},"steps":{"head":"Обязанности и качества продавца, по шагам","items":["Обязанности: знать ассортимент и цены; встречать клиента; выяснять потребность; советовать; оформлять покупку и чек; следить за порядком на полке. Три главных качества:","Вежливость и доброжелательность","Умение слушать и задавать вопросы","Честность — не советовать то, что не подходит. Ещё важны терпение и знание товара. Как выяснить потребность: вопрос 1 — «Для кого/для чего?»; вопрос 2 — «Что для вас важно?»; вопрос 3 — «На какую сумму рассчитываете?»"]},"scheme":"Человечек-продавец, от него 3 стрелки-качества: «Вежлив», «Слушает», «Честен». Внизу «три ключа-вопроса»: для кого/для чего — что важно — сколько.","examples":[{"lab":"Казахстан","text":"Продавец в книжном магазине Алматы спрашивает: «Для кого книга?» — «Брату, 8 лет». — «Что он любит?» — «Динозавров». — «На какую сумму?» — «До 4000 тенге». Предлагает энциклопедию о динозаврах за 3600 тенге. Остаток 400 тенге."},{"lab":"Мир","text":"Во многих странах продавцов магазинов электроники обучают сначала спрашивать, для чего нужна техника, а потом советовать модель."}],"mistake":{"myth":"«Хороший продавец — тот, кто продаёт самое дорогое»","fix":"Если товар не подошёл, клиент вернёт его и не придёт снова; хороший продавец — тот, к кому возвращаются."},"check":[{"q":"Зачем спрашивать о бюджете?","a":"Чтобы предложить товар по карману"},{"q":"4000 − 3600 = ?","a":"400 тенге"}],"kz":{"text":"Казахстан участвует в движении WorldSkills и проводит национальные чемпионаты профессионального мастерства для молодых специалистов колледжей.","link":"профессии сферы продаж и обслуживания требуют навыков общения, которые можно тренировать."},"world":{"text":"Во многих странах проводят конкурсы профессионального мастерства, например WorldSkills, где молодые специалисты показывают умения в разных профессиях, в том числе в сфере обслуживания.","link":""},"fact":"Международное движение WorldSkills проводит чемпионаты профессионального мастерства с 1950 года; первый конкурс прошёл в Испании.","cards":[{"n":"1","title":"Паспорт профессии «Продавец» (seller)","lines":["Чем занимается: ____","3 обязанности: 1) ___ 2) ___ 3) ___","3 главных качества: 1) ___ 2) ___ 3) ___","Где работает: магазин, рынок, интернет-магазин, ярмарка."],"hand":"Сдать: паспорт.","answers":[]},{"n":"2","title":"Игра «Продавец»","lines":["Ассортимент: энциклопедия о динозаврах — 3600 тенге; набор красок — 2500 тенге; мяч — 4000 тенге; пазл — 3000 тенге; книга сказок — 2200 тенге.","Тайные потребности покупателя (выдаёт тренер):","А. Подарок брату 8 лет, любит динозавров, до 4000 тенге. (Энциклопедия, остаток 400.)","Б. Себе для уроков рисования, до 3000 тенге. (Краски, остаток 500.)","В. Бабушке, любит читать внукам, до 2500 тенге. (Сказки, остаток 300.)","Продавец задаёт 3 вопроса: для кого/для чего? что важно? на какую сумму?"],"hand":"Сдать: записанную потребность и предложенный товар.","answers":[]}],"practice":[{"type":"scene","title":"Продавец мечты","minutes":7,"setting":"Покупатели описывают, каким должен быть продавец, а продавец старается быть таким.","roles":[{"name":"Продавец","task":"Улыбаешься, слушаешь, помогаешь."},{"name":"Покупатель-торопыга","task":"Спешишь и хочешь купить быстро."},{"name":"Покупатель-сомневающийся","task":"Долго выбираешь и задаёшь вопросы."}],"steps":["Подходит торопыга.","Подходит сомневающийся.","Продавец помогает обоим по-разному."],"freeze":["Стоп-кадр! Какие качества показал продавец?"],"twist":"Поворот: оба покупателя подошли одновременно. Кого обслужить первым?","debrief":["Какие 3 качества нужны хорошему продавцу?"]},{"type":"scene","title":"Три вопроса покупателю","minutes":6,"setting":"Продавец узнаёт, что нужно покупателю, тремя вопросами.","roles":[{"name":"Продавец","task":"Задаёшь 3 вопроса: для кого? для чего? какой бюджет?"},{"name":"Покупатель","task":"Ищешь подарок другу, но не знаешь какой."}],"steps":["Вопрос 1.","Вопрос 2.","Вопрос 3.","Продавец предлагает товар."],"freeze":["Стоп-кадр! Что продавец узнал из вопросов?"],"twist":null,"debrief":["Почему вопросы помогают продать?"]},{"type":"scene","title":"День в профессии","minutes":5,"setting":"Продавец, кассир и мерчендайзер показывают свою работу.","roles":[{"name":"Продавец-консультант","task":"Помогаешь выбрать."},{"name":"Кассир","task":"Пробиваешь покупку."},{"name":"Мерчендайзер","task":"Красиво раскладываешь товар на полке."}],"steps":["Каждый показывает свою работу.","Класс угадывает профессию."],"freeze":["Стоп-кадр! Чем эти профессии отличаются?"],"twist":null,"debrief":["Какие профессии есть в торговле?"]}],"homework":"Понаблюдать в магазине за продавцом (с родителями) и отметить, какие из 3 качеств он показал.","support":"Список качеств на выбор и готовые «три ключа-вопроса» на карточке.","advanced":"Сыграть продавца для «трудного» покупателя, который не знает, чего хочет, и помочь ему вопросами.","photo":{"src":"lessons/img/04_22.jpg","author":"Blake Wisz","q":["Что вы видите на фото? Как это связано с нашей темой?","Какие качества продавца нужны в любой стране мира?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g04-l22.pptx","name":"22. Продавец в мире профессий (4 кл).pptx","mb":1.5}},{"id":"04_23","g":4,"l":23,"topic":"Взаимодействие во время продаж","module":"Коммуникации и продажи","format":"Тренинг навыка","skills":["Работа с клиентом","Переговоры"],"goal":"К концу урока ученик сможет в ролевой игре поприветствовать покупателя, выслушать его, подобрать фразу под тип клиента и поблагодарить за покупку.","criteria":["Я приветствую покупателя, смотрю на него и улыбаюсь.","Я слушаю, не перебиваю и пересказываю, что понял.","Я благодарю за покупку и подбираю фразу под тип клиента."],"result":"Ролевая сценка «Продавец и покупатель» с тремя обязательными шагами (приветствие — слушание — благодарность) и таблица фраз для 4 типов клиентов.","stages":[{"stage":"Разминка «Правда или ловушка?»","min":5},{"stage":"Показ навыка","min":6},{"stage":"Отработка в парах","min":12},{"stage":"Обратная связь","min":7},{"stage":"Повторная попытка","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"truth","name":"Правда или ловушка?","rules":["Учитель читает слово урока и объяснение — правильное или «перепутанное».","10 секунд молча решаем, так ли объясняется слово.","«Три-два-один!» — все сразу показывают: ладонь вверх = ПРАВДА, кулак = ЛОВУШКА."],"items":[{"term":"Продажи (sales)","real":"Обмен товара на деньги, когда товар помогает покупателю","shown":"Обмен товара на деньги, когда товар помогает покупателю","truth":true,"first":"П"},{"term":"Коммуникация (communication)","real":"Общение: слова, голос, жесты, взгляд","shown":"Договорённости, как разговаривать вежливо и с уважением","truth":false,"first":"К"},{"term":"Клиент","real":"Человек, который покупает товар или услугу","shown":"Человек, который покупает товар или услугу","truth":true,"first":"К"},{"term":"Тип клиента","real":"Особенность поведения покупателя: спешит, сомневается, много спрашивает, молчит","shown":"Общение: слова, голос, жесты, взгляд","truth":false,"first":"Т"},{"term":"Активное слушание","real":"Когда показываешь, что слушаешь: киваешь, уточняешь, пересказываешь","shown":"Когда показываешь, что слушаешь: киваешь, уточняешь, пересказываешь","truth":true,"first":"А"},{"term":"Правила общения","real":"Договорённости, как разговаривать вежливо и с уважением","shown":"Особенность поведения покупателя: спешит, сомневается, много спрашивает, молчит","truth":false,"first":"П"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Продажи (sales)","def":"Обмен товара на деньги, когда товар помогает покупателю"},{"term":"Коммуникация (communication)","def":"Общение: слова, голос, жесты, взгляд"},{"term":"Клиент","def":"Человек, который покупает товар или услугу"},{"term":"Тип клиента","def":"Особенность поведения покупателя: спешит, сомневается, много спрашивает, молчит"},{"term":"Активное слушание","def":"Когда показываешь, что слушаешь: киваешь, уточняешь, пересказываешь"},{"term":"Правила общения","def":"Договорённости, как разговаривать вежливо и с уважением"}],"english":"sales — продажи; communication — коммуникация","concepts":{"head":"Понятия","items":["Коммуникация (communication) в продажах (sales) — не только слова, но и голос, взгляд, жесты.","Активное слушание: кивнуть, уточнить, пересказать («Правильно я понял, вам нужно…?»).","Тип клиента — как он себя ведёт."]},"steps":{"head":"Как вести общение, по шагам","items":["Приветствие: улыбка, взгляд, «Здравствуйте! Чем могу помочь?»","Слушание: не перебивать, кивать, задать уточняющий вопрос","Пересказ: «То есть вам нужно…»","Предложение","Благодарность: «Спасибо за покупку! Приходите ещё!». Четыре типа клиентов и фразы: спешащий — «Покажу самое подходящее за минуту»; сомневающийся — «Давайте сравним два варианта»; любознательный — «Хороший вопрос, расскажу подробнее»; молчаливый — «Можно я задам пару вопросов, чтобы помочь?». Правила общения: вежливо, спокойно, на «вы» со взрослыми, без давления"]},"scheme":"Пять шагов общения слева направо; ниже 4 карточки-типа клиентов с фразами.","examples":[{"lab":"Казахстан","text":"В кофейне Астаны спешащий клиент берёт кофе за 1200 тенге; бариста говорит: «Готово за 2 минуты! Спасибо!» — и клиент возвращается каждое утро. Если за неделю он купил 5 раз, это 6000 тенге."},{"lab":"Мир","text":"В японских магазинах продавцы встречают каждого покупателя приветствием, и это стало частью культуры обслуживания."}],"mistake":{"myth":"Продавец перебивает и сразу предлагает своё","fix":"Игра «данетки» — продавец может задавать только вопросы, на которые отвечают «да» или «нет», пока не поймёт, что нужно клиенту."},"check":[{"q":"Что такое активное слушание?","a":"Кивать, уточнять, пересказывать"},{"q":"Какую фразу сказать сомневающемуся?","a":"«Давайте сравним два варианта»"},{"q":"5 покупок по 1200 тенге?","a":"6000 тенге"}],"kz":{"text":"Казахское гостеприимство — традиция встречать гостя тепло и угощать за дастарханом, даже незнакомого путника.","link":"в продажах приветствие и внимание к клиенту — продолжение этой традиции."},"world":{"text":"В Японии существует культура «омотэнаси» — искреннего гостеприимства: в магазинах и кафе каждого гостя встречают приветствием и обслуживают внимательно. Её связывают с японской чайной церемонией.","link":""},"fact":"Японское слово «омотэнаси» прозвучало на весь мир в 2013 году, когда Токио представлял заявку на Олимпийские игры 2020 года и обещал гостям особое гостеприимство.","cards":[{"n":"1","title":"Фразы для типов клиентов","lines":["Спешащий: ____ (пример: «Покажу самое подходящее за минуту».)","Сомневающийся: ____ («Давайте сравним два варианта».)","Любознательный: ____ («Хороший вопрос, расскажу подробнее».)","Молчаливый: ____ («Можно я задам пару вопросов, чтобы помочь?»)"],"hand":"Сдать: таблицу фраз.","answers":[]},{"n":"2","title":"Роли покупателя (вытянуть)","lines":["А. Спешу на автобус, нужна бутылка воды.","Б. Не могу выбрать между двумя рюкзаками (9 500 и 11 000 тенге).","В. Хочу знать всё о термосе: сколько держит тепло, из чего сделан.","Г. Молчу, смотрю на полку с подарками, нужен подарок маме.","Шаги продавца: приветствие — слушание — пересказ — предложение — благодарность."],"hand":"Сдать: проведённую сценку.","answers":[]},{"n":"3","title":"Данетка для повторной попытки","lines":["Клиент загадал товар (например, зонт). Продавец задаёт только вопросы «да/нет»: «Это для улицы?», «Это нужно в плохую погоду?»… пока не угадает."],"hand":"Сдать: отгаданный товар и число вопросов.","answers":[]}],"practice":[{"type":"scene","title":"Глаза, улыбка, имя","minutes":7,"setting":"Продавец встречает покупателя: смотрит в глаза, улыбается и вежливо здоровается.","roles":[{"name":"Продавец","task":"Приветствуешь, смотришь на покупателя, улыбаешься."},{"name":"Покупатель","task":"Входишь в магазин немного хмурый."},{"name":"Наблюдатель","task":"Отмечаешь, что продавец сделал правильно."}],"steps":["Покупатель входит.","Продавец приветствует.","Наблюдатель называет удачные действия."],"freeze":["Стоп-кадр! Изменилось ли настроение покупателя?"],"twist":"Поворот: продавец разговаривает по телефону, когда входит покупатель. Как поступить?","debrief":["Почему первые секунды встречи так важны?"]},{"type":"scene","title":"Слушаю и пересказываю","minutes":6,"setting":"Покупатель долго объясняет, что ищет. Продавец слушает и пересказывает.","roles":[{"name":"Покупатель","task":"Подробно описываешь, что тебе нужно."},{"name":"Продавец","task":"Не перебиваешь, потом пересказываешь: «Правильно я понял, что…»"}],"steps":["Покупатель объясняет.","Продавец пересказывает.","Покупатель подтверждает."],"freeze":["Стоп-кадр! Зачем пересказывать?"],"twist":null,"debrief":["Как показать, что ты слушаешь?"]},{"type":"scene","title":"Разные покупатели","minutes":5,"setting":"К продавцу приходят разные покупатели: весёлый, молчаливый и сердитый.","roles":[{"name":"Продавец","task":"Подбираешь фразу под каждого."},{"name":"Весёлый покупатель","task":"Шутишь."},{"name":"Молчаливый покупатель","task":"Отвечаешь коротко."},{"name":"Сердитый покупатель","task":"Недоволен очередью."}],"steps":["Каждый покупатель подходит.","Продавец отвечает по-разному."],"freeze":["Стоп-кадр! С кем было сложнее всего?"],"twist":null,"debrief":["Почему к разным покупателям нужен разный подход?"]}],"homework":"Использовать дома или в магазине 3 шага: приветствие, слушание, благодарность — и рассказать, как отреагировали люди.","support":"Готовые фразы для каждого шага на карточке и тип клиента «спешащий» как самый простой.","advanced":"Сыграть сразу двух клиентов разного типа, которые подошли вместе, и вежливо обслужить обоих.","photo":{"src":"lessons/img/04_23.jpg","author":"Radission US","q":["Что вы видите на фото? Как это связано с нашей темой?","Что из этой культуры можно применить на нашей ярмарке?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g04-l23.pptx","name":"23. Взаимодействие во время продаж (4 кл).pptx","mb":1.4}},{"id":"04_24","g":4,"l":24,"topic":"Работа с возражениями","module":"Коммуникации и продажи","format":"Комбинированный","skills":["Переговоры","Работа с клиентом","Финансовое мышление"],"goal":"К концу урока ученик сможет вежливо ответить на 2 возражения покупателя — «дорого» и «я подумаю» — по схеме «согласиться — уточнить — аргумент» с одним фактом о товаре.","criteria":["Я не спорю, а соглашаюсь с чувством покупателя.","Я задаю уточняющий вопрос.","Я привожу честный аргумент с фактом или расчётом."],"result":"Две готовые реплики-ответа на возражения «дорого» и «я подумаю» для своего товара и выступление на «Стуле возражений».","stages":[{"stage":"Разминка «Угадай слово»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"guess","name":"Угадай слово","rules":["Слово спрятано — звучит только его объяснение и первая буква.","10 секунд команда шёпотом выбирает одно слово.","«Три-два-один!» — все команды хором называют слово. Верно — балл команде."],"items":[{"term":"Возражение (objection)","real":"Сомнение или отказ покупателя: «дорого», «я подумаю», «мне не нужно»","shown":"Сомнение или отказ покупателя: «дорого», «я подумаю», «мне не нужно»","truth":true,"first":"В"},{"term":"Коммуникация (communication)","real":"Общение и обмен информацией","shown":"Сомнение с настоящей причиной: «дорого для меня», «боюсь, что сломается»","truth":false,"first":"К"},{"term":"Клиент","real":"Человек, который покупает","shown":"Человек, который покупает","truth":true,"first":"К"},{"term":"Аргумент","real":"Довод, факт, который объясняет, почему стоит купить","shown":"Общение и обмен информацией","truth":false,"first":"А"},{"term":"Необоснованный отказ","real":"Вежливое «нет» без настоящей причины: «я подумаю», «мне ничего не надо»","shown":"Вежливое «нет» без настоящей причины: «я подумаю», «мне ничего не надо»","truth":true,"first":"Н"},{"term":"Обоснованное возражение","real":"Сомнение с настоящей причиной: «дорого для меня», «боюсь, что сломается»","shown":"Довод, факт, который объясняет, почему стоит купить","truth":false,"first":"О"}],"perm":[1,0,5,4,3,2]},"glossary":[{"term":"Возражение (objection)","def":"Сомнение или отказ покупателя: «дорого», «я подумаю», «мне не нужно»"},{"term":"Коммуникация (communication)","def":"Общение и обмен информацией"},{"term":"Клиент","def":"Человек, который покупает"},{"term":"Аргумент","def":"Довод, факт, который объясняет, почему стоит купить"},{"term":"Необоснованный отказ","def":"Вежливое «нет» без настоящей причины: «я подумаю», «мне ничего не надо»"},{"term":"Обоснованное возражение","def":"Сомнение с настоящей причиной: «дорого для меня», «боюсь, что сломается»"}],"english":"objection — возражение; communication — коммуникация","concepts":{"head":"Понятия","items":["Возражение (objection) — нормальная часть продажи: клиент сомневается.","Необоснованный отказ — без причины («я подумаю»).","Обоснованное — с причиной («дорого»).","Аргумент — честный факт."]},"scheme":"Три ступени: «Понимаю вас» → «Что именно…?» → «Факт: …». Справа два облачка-возражения «Дорого» и «Я подумаю» с примерами ответов. Внизу красная рамка «Нельзя: спорить, давить, пугать».","examples":[{"lab":"Казахстан","text":"Продавец термоса на ярмарке в Павлодаре. Клиент: «Дорого — 4500 тенге». Продавец: «Понимаю. Вы каждый день покупаете чай в школе? — Да, по 300 тенге. — Если брать чай из дома, термос окупится за 15"},{"lab":"Школьных дней","text":"300 × 15 = 4500». Клиент: «Я подумаю». Продавец: «Конечно. Что поможет решить — сравнить с другим термосом? Вот наша листовка»."},{"lab":"Мир","text":"В магазинах многих стран продавцов учат: возражение — это вопрос клиента, а не отказ навсегда."}],"mistake":{"myth":"Продавец спорит: «Нет, не дорого!»","fix":"«Стул возражений» — сравнить, как чувствует себя «покупатель», когда с ним спорят и когда его понимают."},"check":[{"q":"С чего начинаем ответ на возражение?","a":"Согласиться с чувством"},{"q":"Почему «я подумаю» — часто необоснованный отказ?","a":"Нет настоящей причины, её надо уточнить"},{"q":"300 × 15 = ?","a":"4500 тенге"}],"kz":{"text":"Ярмарки выходного дня в городах Казахстана, где фермеры продают мёд, мясо, овощи. Продавцы часто слышат «дорого» и отвечают фактами: «Мёд с нашей пасеки, без сахара, можно попробовать».","link":"дегустация и честный факт — лучший ответ на возражение."},"world":{"text":"Во многих странах в законах о защите потребителей запрещены агрессивные продажи — когда покупателя запугивают или давят на него. Покупатель всегда имеет право отказаться.","link":""},"fact":"Дегустации в магазинах появились ещё в конце XIX века: например, на Всемирной выставке в Чикаго в 1893 году компании угощали посетителей новыми продуктами, чтобы те убедились сами.","cards":[{"n":"1","title":"Мои ответы на возражения (objection)","lines":["Товар: ____ Цена: ____ тенге.","«Дорого»:","1) Согласиться: «Понимаю вас…»","2) Уточнить: «Скажите, …?»","3) Аргумент с фактом или расчётом: ____","«Я подумаю»:","1) «Конечно, …»","2) «Что поможет решить — …?»","3) Предложение: листовка, сравнение, время работы.","Пример: термос 4500 тенге окупится за 15 дней, если не покупать чай по 300 тенге (300 × 15 = 4500)."],"hand":"Сдать: 2 ответа.","answers":[]},{"n":"2","title":"Стул возражений","lines":["Возражения для покупателей (по очереди): «Дорого», «Я подумаю», «Мне не нужно», «А он не сломается?», «У соседа дешевле».","Продавец отвечает по 3 ступеням. Нельзя: спорить, давить, пугать.","Оценка группы: согласился — да/нет, уточнил — да/нет, аргумент — да/нет."],"hand":"Сдать: отметки группы.","answers":[]}],"practice":[{"type":"scene","title":"«Слишком дорого!»","minutes":7,"setting":"Покупатель говорит, что товар дорогой. Продавец отвечает по схеме: согласиться с чувством, уточнить, привести факт.","roles":[{"name":"Покупатель","task":"Говоришь: «Слишком дорого!»"},{"name":"Продавец","task":"Отвечаешь по схеме: «Понимаю… Сравниваете с чем?… Зато…»"},{"name":"Тренер","task":"Проверяешь, все ли 3 шага сделаны."}],"steps":["Покупатель возражает.","Продавец проходит 3 шага.","Тренер отмечает шаги."],"freeze":["Стоп-кадр! Какой шаг продавец пропустил?"],"twist":"Поворот: покупатель говорит: «В другом магазине дешевле». Что ответить честно?","debrief":["Почему не надо спорить с покупателем?"]},{"type":"scene","title":"«Мне надо подумать»","minutes":6,"setting":"Покупатель не готов купить сразу.","roles":[{"name":"Покупатель","task":"Говоришь: «Мне надо подумать»."},{"name":"Продавец","task":"Уточняешь, что смущает, и не давишь."}],"steps":["Возражение.","Уточняющий вопрос.","Ответ."],"freeze":["Стоп-кадр! Давил ли продавец?"],"twist":null,"debrief":["Как помочь покупателю решить, не давя?"]},{"type":"scene","title":"Спорщик и мудрец","minutes":5,"setting":"Два продавца отвечают на одно возражение: один спорит, другой соглашается с чувством.","roles":[{"name":"Продавец-спорщик","task":"Споришь: «Нет, не дорого!»"},{"name":"Продавец-мудрец","task":"Говоришь: «Понимаю вас…»"},{"name":"Покупатель","task":"Выбираешь, у кого купить."}],"steps":["Возражение спорщику.","Возражение мудрецу.","Выбор покупателя."],"freeze":["Стоп-кадр! Почему спорщик проиграл?"],"twist":null,"debrief":["Какая первая фраза помогает в споре?"]}],"homework":"Подготовить ответ на возражение «мне не нужно» для товара к ярмарке по схеме из 3 ступеней.","support":"Шаблон ответов с пропусками: «Понимаю вас. Скажите, … ? Наш товар …, потому что …».","advanced":"Ответить на 3-е возражение «у соседа дешевле» честным аргументом без критики соседа.","photo":{"src":"lessons/img/04_24.jpg","author":"Radission US","q":["Что вы видите на фото? Как это связано с нашей темой?","Как понять, что продавец уже давит, а не помогает?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g04-l24.pptx","name":"24. Работа с возражениями (4 кл).pptx","mb":1.3}},{"id":"04_25","g":4,"l":25,"topic":"Ярмарка: работа с возражениями покупателя","module":"Коммуникации и продажи","format":"Симуляция, ярмарка","skills":["Переговоры","Работа с клиентом","Командная работа"],"goal":"К концу урока ученик сможет на ярмарке ответить хотя бы на 2 возражения покупателей по схеме «согласиться — уточнить — аргумент», записать их и посчитать выручку команды.","criteria":["Я отвечаю на возражения вежливо и честно, по схеме.","Я записываю возражения и итог: купили или нет.","Я правильно считаю выручку команды."],"result":"Работа команды на ярмарке: продажи с ответами на возражения, «журнал возражений» (какие были и чем ответили) и выручка в тенге.","stages":[{"stage":"Разминка «Найди пару»","min":4},{"stage":"Подготовка","min":6},{"stage":"Ярмарка","min":18},{"stage":"Подсчёт","min":7},{"stage":"Рефлексия","min":5}],"warm":{"kind":"match","name":"Найди пару","rules":["На экране определения под номерами.","Учитель называет слово, например: «Слово А — …». 10 секунд на поиск.","Все одновременно показывают номер подходящего определения на пальцах."],"items":[{"term":"Ярмарка (fair)","real":"Праздничный рынок на один день","shown":"Праздничный рынок на один день","truth":true,"first":"Я"},{"term":"Покупатель (customer)","real":"Человек, который покупает товар","shown":"Все деньги за проданные товары","truth":false,"first":"П"},{"term":"Возражение","real":"Сомнение покупателя: «дорого», «я подумаю»","shown":"Сомнение покупателя: «дорого», «я подумаю»","truth":true,"first":"В"},{"term":"Аргумент","real":"Честный довод о товаре","shown":"Человек, который покупает товар","truth":false,"first":"А"},{"term":"Журнал возражений","real":"Таблица, куда записывают возражения и ответы","shown":"Таблица, куда записывают возражения и ответы","truth":true,"first":"Ж"},{"term":"Выручка","real":"Все деньги за проданные товары","shown":"Честный довод о товаре","truth":false,"first":"В"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Ярмарка (fair)","def":"Праздничный рынок на один день"},{"term":"Покупатель (customer)","def":"Человек, который покупает товар"},{"term":"Возражение","def":"Сомнение покупателя: «дорого», «я подумаю»"},{"term":"Аргумент","def":"Честный довод о товаре"},{"term":"Журнал возражений","def":"Таблица, куда записывают возражения и ответы"},{"term":"Выручка","def":"Все деньги за проданные товары"}],"english":"fair — ярмарка; customer — покупатель","concepts":{"head":"Понятия","items":["Возражение — сомнение покупателя (customer).","Аргумент — честный факт.","Журнал возражений — записи для разбора.","Выручка — деньги за продажи на ярмарке (fair)."]},"steps":{"head":"Как работать на ярмарке, по шагам","items":["Роли — продавцы, «аргументник» (знает факты о товаре), секретарь журнала, кассир","Подготовить 3 аргумента о товаре и ответы на «дорого», «я подумаю», «мне не нужно»","Встречать покупателя, выяснять потребность","На возражение: «Понимаю вас» → уточнить → аргумент","Записать в журнал: возражение, ответ, купил или нет","Посчитать выручку. Покупатели в этой ярмарке специально получают карточки возражений"]},"scheme":"Таблица журнала: «Возражение | Наш ответ | Купили? (да/нет)». Внизу: «Выручка = количество × цена».","examples":[{"lab":"Казахстан","text":"Команда продаёт закладки с орнаментом по 300 тенге. Покупатель: «Дорого». Ответ: «Понимаю. Для чего вам закладка? — Для учебника. — Она ламинированная, прослужит весь год, а бумажные рвутся за месяц». Купил. Итог: 12 возражений, после 7 ответов купили — 7 из 12. Продали 14 закладок: 14 × 300 = 4200 тенге."},{"lab":"Мир","text":"На рождественских ярмарках Европы продавцы угощают пробником, отвечая на «я подумаю»."}],"mistake":{"myth":"Продавец «догоняет» покупателя и уговаривает несколько раз","fix":"Правило ярмарки — одно возражение, один честный ответ, потом уважаем решение."},"check":[{"q":"Что делать, если покупатель всё равно сказал «нет»?","a":"Поблагодарить, отпустить, записать"},{"q":"Купили 7 из 12 — больше половины?","a":"Да"},{"q":"14 × 300 = ?","a":"4200 тенге"}],"kz":{"text":"Ярмарки выходного дня в Казахстане: фермеры и мастера продают свои товары и каждый день слышат возражения покупателей.","link":"продавец, который спокойно отвечает фактами, продаёт больше и получает постоянных клиентов."},"world":{"text":"На рождественских ярмарках Германии и Австрии продавцы часто дают попробовать пряники или напитки — это честный ответ на сомнение «я подумаю».","link":""},"fact":"Немецкие рождественские ярмарки известны с позднего Средневековья; ярмарке в Дрездене — «Штрицельмаркт» — больше 500 лет, её первое упоминание относят к 1434 году.","cards":[{"n":"1","title":"Подготовка команды","lines":["Роли: продавцы ___, «аргументник» ___, секретарь ___, кассир ___.","Наш товар и цена: ____","3 честных аргумента: 1) ___ 2) ___ 3) ___","Ответ на «Дорого»: ____","Ответ на «Я подумаю»: ____","Ответ на «Мне не нужно»: ____"],"hand":"Сдать: карточку.","answers":[]},{"n":"2","title":"Карточки возражений для покупателей","lines":["«Дорого.» / «Я подумаю.» / «Мне не нужно.» / «А он не сломается?» / «У соседей дешевле.» / «Мне не нравится цвет.»","Правило: покупатель говорит возражение и покупает, если ответ вежливый и честный."],"hand":"Сдать: использованные карточки.","answers":[]},{"n":"3","title":"Журнал возражений и выручка","lines":["Возражение | Наш ответ | Купили?","Всего возражений: ___ Купили после ответа: ___ из ___","Продали товаров: ___ × цена ___ = выручка ___ тенге.","Пример: 14 × 300 = 4200 тенге."],"hand":"Сдать: журнал.","answers":[["","Да/нет"]]}],"practice":[{"type":"scene","title":"Возражения на ярмарке","minutes":7,"setting":"На ярмарке покупатели возражают, а команда отвечает по схеме и записывает итог.","roles":[{"name":"Продавец","task":"Отвечаешь на возражения вежливо."},{"name":"Покупатель 1","task":"«Дорого»."},{"name":"Покупатель 2","task":"«А он не сломается?»"},{"name":"Учётчик","task":"Записываешь возражение и итог: купили или нет."}],"steps":["Покупатели возражают по очереди.","Продавец отвечает.","Учётчик записывает."],"freeze":["Стоп-кадр! Какое возражение было чаще?"],"twist":"Поворот: покупатель просит попробовать товар. Разрешим?","debrief":["Что помогает отвечать на возражения?"]},{"type":"scene","title":"Таблица возражений","minutes":6,"setting":"Команда заполняет таблицу: возражение — ответ — купили?","roles":[{"name":"Учётчик","task":"Заполняешь таблицу."},{"name":"Продавец","task":"Вспоминаешь ответы."}],"steps":["Вспоминаем возражения.","Записываем ответы.","Отмечаем итог."],"freeze":["Стоп-кадр! Какой ответ сработал?"],"twist":null,"debrief":["Зачем записывать возражения?"]},{"type":"scene","title":"«У соседей дешевле!»","minutes":5,"setting":"На ярмарке покупатель говорит: «У соседнего стола такой же браслет дешевле».","roles":[{"name":"Покупатель","task":"Сравниваешь с соседним столом."},{"name":"Продавец","task":"Не споришь: соглашаешься с чувством, уточняешь, называешь честную пользу."},{"name":"Учётчик","task":"Записываешь возражение и итог."}],"steps":["Возражение.","Ответ по схеме.","Учётчик записывает: купили или нет."],"freeze":["Стоп-кадр! Продавец спорил или соглашался с чувством?"],"twist":null,"debrief":["Как честно ответить, если у конкурента дешевле?"]}],"homework":"Записать дома одно возражение, которое родители сказали бы о твоём товаре, и придумать честный ответ.","support":"Карточка с готовыми ответами на «дорого» и «я подумаю»; роль секретаря журнала.","advanced":"Отвечать на самые трудные возражения («у соседа дешевле») и посчитать, какая доля возражений закончилась покупкой (словами: «7 из 12»).","photo":{"src":"lessons/img/04_25.jpg","author":"Jonathan Borba","q":["Что вы видите на фото? Как это связано с нашей темой?","Какой честный «пробник» можно сделать для нашего товара?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g04-l25.pptx","name":"25. Ярмарка — работа с возражениями покупателя (4 кл).pptx","mb":1.9}},{"id":"04_26","g":4,"l":26,"topic":"Как продаются товары. Продажа","module":"Коммуникации и продажи","format":"Тренинг навыка","skills":["Переговоры","Презентация","Работа с клиентом"],"goal":"К концу урока ученик сможет подготовить и произнести за 30 секунд короткое предложение своего товара для выбранного покупателя по схеме «Вам нужно… — Наш товар… — Польза… — Цена… — Предложение».","criteria":["Моё предложение обращено к конкретному покупателю и его потребности.","В нём есть польза, цена и предложение действия.","Я уложился в 30 секунд и улучшил текст после обратной связи."],"result":"Текст короткого предложения товара (5 частей, до 30 секунд) для конкретного покупателя, отработанный в диалоге с партнёром дважды.","stages":[{"stage":"Разминка «Правда или ловушка?»","min":5},{"stage":"Показ навыка","min":6},{"stage":"Отработка в парах","min":12},{"stage":"Обратная связь","min":7},{"stage":"Повторная попытка","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"truth","name":"Правда или ловушка?","rules":["Учитель читает слово урока и объяснение — правильное или «перепутанное».","10 секунд молча решаем, так ли объясняется слово.","«Три-два-один!» — все сразу показывают: ладонь вверх = ПРАВДА, кулак = ЛОВУШКА."],"items":[{"term":"Продажа (sales)","real":"Обмен товара или услуги на деньги, подтверждённый чеком","shown":"Обмен товара или услуги на деньги, подтверждённый чеком","truth":true,"first":"П"},{"term":"Товар (product)","real":"Вещь, которую делают для продажи","shown":"Что хорошего получит покупатель","truth":false,"first":"Т"},{"term":"Переговоры","real":"Разговор, в котором стороны договариваются об условиях","shown":"Разговор, в котором стороны договариваются об условиях","truth":true,"first":"П"},{"term":"Коммуницировать","real":"Общаться, передавать и получать информацию","shown":"Вещь, которую делают для продажи","truth":false,"first":"К"},{"term":"Предложение товара","real":"Короткий рассказ, почему товар нужен именно этому покупателю","shown":"Короткий рассказ, почему товар нужен именно этому покупателю","truth":true,"first":"П"},{"term":"Польза","real":"Что хорошего получит покупатель","shown":"Общаться, передавать и получать информацию","truth":false,"first":"П"}],"perm":[3,2,1,0,5,4]},"glossary":[{"term":"Продажа (sales)","def":"Обмен товара или услуги на деньги, подтверждённый чеком"},{"term":"Товар (product)","def":"Вещь, которую делают для продажи"},{"term":"Переговоры","def":"Разговор, в котором стороны договариваются об условиях"},{"term":"Коммуницировать","def":"Общаться, передавать и получать информацию"},{"term":"Предложение товара","def":"Короткий рассказ, почему товар нужен именно этому покупателю"},{"term":"Польза","def":"Что хорошего получит покупатель"},{"term":"Чек","def":"Документ, который подтверждает продажу"}],"english":"product — товар; sales — продажи","concepts":{"head":"Понятия","items":["Продажа (sales) — обмен товара (product) на деньги, который подтверждают чеком.","Переговоры — договариваемся об условиях: цена, количество, доставка.","Коммуницировать — общаться.","Предложение товара — 30 секунд о пользе для конкретного покупателя."]},"steps":{"head":"Как построить предложение, по шагам","items":["Выбрать покупателя (кто он, что ему нужно)","«Вам нужно…» — назвать потребность","«Наш товар…» — что это","«Польза…» — 1–2 выгоды именно для него","«Цена…» — честно","«Предлагаю…» — действие: попробовать, взять 2, оформить. Затем диалог: продавец слушает ответ и договаривается (переговоры)"]},"scheme":"Пять окошек в ряд: «Вам нужно…» → «Наш товар…» → «Польза…» → «Цена…» → «Предлагаю…». Под ними — таймер 30 секунд и стрелка «Диалог: слушаю ответ».","examples":[{"lab":"Казахстан","text":"Покупатель — мама первоклассника в Костанае. «Вам нужно, чтобы ребёнок был виден вечером на дороге? Наш светоотражающий брелок с орнаментом крепится к рюкзаку. Его видно водителю издалека. Цена — 1500 тенге. Если возьмёте 2 — для рюкзака и куртки — 2800 тенге». Экономия: 1500 × 2 − 2800 = 200 тенге."},{"lab":"Мир","text":"В мире бизнеса есть «речь для лифта» — короткая презентация на 30 секунд, пока едешь в лифте с собеседником."}],"mistake":{"myth":"Одно и то же предложение для всех («Купите, он хороший!»)","fix":"Сказать одно предложение для бабушки и для школьника — польза разная."},"check":[{"q":"С чего начинается предложение?","a":"С потребности покупателя"},{"q":"Зачем называть цену честно?","a":"Чтобы клиент доверял"},{"q":"1500 × 2 − 2800 = ?","a":"200 тенге экономии"}],"kz":{"text":"Astana Hub — международный технопарк IT-стартапов в Астане, где молодые предприниматели коротко презентуют свои проекты.","link":"короткое предложение для конкретного слушателя — основа любой продажи и презентации."},"world":{"text":"Во многих странах предприниматели тренируют «речь для лифта» (elevator pitch) — рассказ о своём деле за 30 секунд. С таким коротким выступлением стартаперы выступают перед инвесторами на конкурсах.","link":""},"fact":"Выражение «elevator pitch» (речь для лифта) объясняют тем, что за поездку в лифте — около 30 секунд — нужно успеть заинтересовать важного собеседника своей идеей.","cards":[{"n":"1","title":"Моё предложение товара (product)","lines":["Покупатель: ____","«Вам нужно …»","«Наш товар — …»","«Польза: … и …»","«Цена — … тенге.»","«Предлагаю …» (попробовать / взять 2 / оформить)","Время: ___ секунд (не больше 30)."],"hand":"Сдать: текст.","answers":[]},{"n":"2","title":"Покупатели","lines":["А. Мама первоклассника: волнуется, что ребёнка не видно вечером на дороге.","Б. Бабушка: любит дарить внукам полезные подарки, бюджет до 5000 тенге.","В. Школьник 10 лет: любит спорт, всё время теряет бутылку для воды.","Г. Турист из другой страны: хочет сувенир о Казахстане.","Задача: брелок 1500 тенге, 2 штуки — 2800 тенге. Экономия?"],"hand":"Сдать: выбор покупателя.","answers":[["","200 тенге."]]}],"practice":[{"type":"scene","title":"Предложение за 30 секунд","minutes":7,"setting":"Продавец делает предложение конкретному покупателю: польза, цена, действие.","roles":[{"name":"Продавец","task":"За 30 секунд: польза, цена, «Берёте?»"},{"name":"Покупатель-спортсмен","task":"Тебе нужна бутылка для воды."},{"name":"Хронометрист","task":"Следишь за 30 секундами."}],"steps":["Продавец говорит.","Хронометрист следит за временем.","Покупатель решает."],"freeze":["Стоп-кадр! Уложился ли продавец?"],"twist":"Поворот: покупатель — бабушка, а не спортсмен. Как изменить предложение?","debrief":["Из чего состоит хорошее предложение?"]},{"type":"scene","title":"Улучши после отзыва","minutes":6,"setting":"Продавец получает отзыв и говорит предложение снова, лучше.","roles":[{"name":"Продавец","task":"Говоришь предложение два раза."},{"name":"Тренер","task":"Даёшь одну подсказку между попытками."}],"steps":["Попытка 1.","Подсказка.","Попытка 2."],"freeze":["Стоп-кадр! Стало ли лучше?"],"twist":null,"debrief":["Почему полезно получать обратную связь?"]},{"type":"scene","title":"Продай классу","minutes":5,"setting":"Каждая команда продаёт классу предмет из пенала.","roles":[{"name":"Продавец команды","task":"Продаёшь предмет классу."},{"name":"Класс","task":"Голосуете, купили бы."}],"steps":["Предложение.","Голосование."],"freeze":["Стоп-кадр! Почему это предложение сработало?"],"twist":null,"debrief":["Что помогает продать?"]}],"homework":"Произнести своё предложение товара родственнику за 30 секунд и спросить, купил бы он и почему.","support":"Шаблон с началом фраз для каждого окошка и покупатель «мама первоклассника» с готовой потребностью.","advanced":"Подготовить предложение для двух покупателей одновременно (например, папа и сын) и найти пользу для обоих.","photo":{"src":"lessons/img/04_26.jpg","author":"Blake Wisz","q":["Что вы видите на фото? Как это связано с нашей темой?","Что самое важное нужно успеть сказать за 30 секунд?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g04-l26.pptx","name":"26. Как продаются товары. Продажа (4 кл).pptx","mb":1.6}},{"id":"04_27","g":4,"l":27,"topic":"После ярмарки: какие были возражения и ответы","module":"Коммуникации и продажи","format":"Симуляция, ярмарка","skills":["Критическое мышление","Переговоры","Командная работа"],"goal":"К концу урока ученик сможет по журналу возражений прошлой ярмарки назвать 3 самых частых возражения, сравнить ответы, которые сработали и не сработали, и проверить улучшенный ответ на мини-ярмарке.","criteria":["Я считаю, какие возражения были чаще всего.","Я объясняю, почему один ответ сработал, а другой нет.","Я улучшаю ответ и проверяю его."],"result":"Таблица анализа возражений команды (частота, удачные и неудачные ответы) и «банк лучших ответов», проверенный на мини-ярмарке.","stages":[{"stage":"Разминка «Угадай слово»","min":4},{"stage":"Подготовка","min":6},{"stage":"Ярмарка","min":18},{"stage":"Подсчёт","min":7},{"stage":"Рефлексия","min":5}],"warm":{"kind":"guess","name":"Угадай слово","rules":["Слово спрятано — звучит только его объяснение и первая буква.","10 секунд команда шёпотом выбирает одно слово.","«Три-два-один!» — все команды хором называют слово. Верно — балл команде."],"items":[{"term":"Ярмарка (fair)","real":"Праздничный рынок на один день","shown":"Праздничный рынок на один день","truth":true,"first":"Я"},{"term":"Возражение (objection)","real":"Сомнение или отказ покупателя","shown":"Что мы поняли по цифрам","truth":false,"first":"В"},{"term":"Журнал возражений","real":"Таблица с возражениями, ответами и итогом","shown":"Таблица с возражениями, ответами и итогом","truth":true,"first":"Ж"},{"term":"Частота","real":"Сколько раз что-то повторилось","shown":"Сомнение или отказ покупателя","truth":false,"first":"Ч"},{"term":"Банк ответов","real":"Собранные лучшие ответы, которыми может пользоваться вся команда","shown":"Собранные лучшие ответы, которыми может пользоваться вся команда","truth":true,"first":"Б"},{"term":"Вывод","real":"Что мы поняли по цифрам","shown":"Сколько раз что-то повторилось","truth":false,"first":"В"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Ярмарка (fair)","def":"Праздничный рынок на один день"},{"term":"Возражение (objection)","def":"Сомнение или отказ покупателя"},{"term":"Журнал возражений","def":"Таблица с возражениями, ответами и итогом"},{"term":"Частота","def":"Сколько раз что-то повторилось"},{"term":"Банк ответов","def":"Собранные лучшие ответы, которыми может пользоваться вся команда"},{"term":"Вывод","def":"Что мы поняли по цифрам"}],"english":"fair — ярмарка; objection — возражение","concepts":{"head":"Понятия","items":["Журнал возражений — записи с ярмарки (fair).","Частота — сколько раз встретилось возражение (objection).","Банк ответов — лучшие ответы команды.","Вывод — что делаем дальше."]},"steps":{"head":"Как разобрать, по шагам","items":["Выписать все возражения из журнала","Посчитать частоту каждого (метками «палочками»)","Найти 3 самых частых","Для каждого сравнить ответы: после какого купили, после какого нет","Найти причину: был ли шаг «согласиться», был ли уточняющий вопрос, был ли честный факт","Записать улучшенный ответ в банк и проверить на мини-ярмарке"]},"scheme":"Столбчатая диаграмма частоты: «Дорого» 7, «Я подумаю» 5, «Не нужно» 3. Рядом таблица: «Возражение | Ответ сработал (да/нет) | Почему | Улучшенный ответ».","examples":[{"lab":"Казахстан","text":"Команда «Орнамент» записала 15 возражений: «Дорого» — 7, «Я подумаю» — 5, «Не нужно» — 3. После ответа на «Дорого» купили 5 из 7 — ответ с расчётом работает. После «Я подумаю» купили 1 из 5 — ответ «Ну подумайте» не работает. Улучшение: «Конечно! Что поможет решить — сравнить с другой закладкой?» На мини-ярмарке купили 3 из 5."},{"lab":"Мир","text":"Во многих компаниях продавцы собирают «базу возражений» и делятся лучшими ответами с новичками."}],"mistake":{"myth":"Команда разбирает только удачные ответы и не смотрит на неудачные","fix":"Самое ценное — понять, почему ответ не сработал."},"check":[{"q":"Какое возражение самое частое?","a":"«Дорого», 7 раз"},{"q":"Купили 5 из 7 — это больше половины?","a":"Да"},{"q":"Почему «Ну подумайте» не работает?","a":"Нет уточнения и аргумента"}],"kz":{"text":"Крупные казахстанские сети, например магазины Technodom, обучают продавцов-консультантов отвечать на частые вопросы покупателей о технике.","link":"собранные ответы на частые вопросы помогают всем продавцам сети."},"world":{"text":"Во многих компаниях мира продавцы ведут общую базу вопросов и возражений клиентов и учатся на ней, а лучшие ответы передают новичкам. Это помогает обслуживать клиентов одинаково хорошо в любом магазине сети.","link":""},"fact":"Раздел «Часто задаваемые вопросы» (FAQ) появился ещё в 1980-е годы в ранних сетевых сообществах, чтобы не отвечать на одни и те же вопросы много раз; сейчас он есть почти на каждом сайте магазина.","cards":[{"n":"1","title":"Частота возражений (objection)","lines":["Выпишите все возражения из журнала и отметьте палочками:","«Дорого» ___ «Я подумаю» ___ «Не нужно» ___ «Сломается?» ___ «У соседей дешевле» ___ Другое ___","3 самых частых: 1) ___ 2) ___ 3) ___","Постройте столбчатую диаграмму (1 клетка = 1 раз).","Пример: «Дорого» 7, «Я подумаю» 5, «Не нужно» 3 — всего 15."],"hand":"Сдать: диаграмму.","answers":[]},{"n":"2","title":"Что сработало?","lines":["Возражение: ___","Ответ, после которого купили: ___ (купили ___ из ___)","Ответ, после которого не купили: ___","Почему: был ли «согласиться»? уточнение? факт?","Улучшенный","Результат на мини-ярмарке: купили ___ из ___"],"hand":"Сдать: карточку.","answers":[["","___"]]}],"practice":[{"type":"scene","title":"Разбор возражений","minutes":7,"setting":"Команда вспоминает возражения на ярмарке и разбирает ответы.","roles":[{"name":"Ведущий","task":"Читаешь возражение из таблицы."},{"name":"Продавец","task":"Вспоминаешь свой ответ."},{"name":"Эксперт","task":"Говоришь, почему ответ сработал или нет."}],"steps":["Возражение.","Ответ.","Разбор эксперта."],"freeze":["Стоп-кадр! Почему этот ответ не сработал?"],"twist":"Поворот: эксперт предлагает новый ответ. Проверим его сценкой?","debrief":["Какое возражение было чаще всего?"]},{"type":"scene","title":"Новый ответ","minutes":6,"setting":"Продавец пробует улучшенный ответ на частое возражение.","roles":[{"name":"Покупатель","task":"Говоришь частое возражение."},{"name":"Продавец","task":"Отвечаешь по-новому."}],"steps":["Возражение.","Новый ответ."],"freeze":["Стоп-кадр! Лучше ли стал ответ?"],"twist":null,"debrief":["Как улучшить ответ на возражение?"]},{"type":"scene","title":"Топ-3 ответа","minutes":5,"setting":"Класс выбирает 3 лучших ответа на возражения.","roles":[{"name":"Ведущий","task":"Читаешь ответы."},{"name":"Класс","task":"Голосуете."}],"steps":["Чтение.","Голосование."],"freeze":["Стоп-кадр! Почему эти ответы лучшие?"],"twist":null,"debrief":["Какие ответы мы запомним?"]}],"homework":"Переписать в тетрадь 3 лучших ответа из «банка ответов» класса и выучить один наизусть.","support":"Журнал с подсказкой-схемой «согласиться — уточнить — аргумент» для анализа ответа.","advanced":"Найти возражение, на которое никто не ответил удачно, и придумать 2 варианта ответа.","photo":{"src":"lessons/img/04_27.jpg","author":"Towfiqu barbhuiya","q":["Что вы видите на фото? Как это связано с нашей темой?","Зачем записывать, а не просто помнить?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g04-l27.pptx","name":"27. После ярмарки — какие были возражения и ответы (4 кл).pptx","mb":1.4}},{"id":"04_28","g":4,"l":28,"topic":"Выручка ярмарки: сколько мы получили","module":"Коммуникации и продажи","format":"Симуляция, ярмарка","skills":["Финансовое мышление","Командная работа","Работа с клиентом"],"goal":"К концу урока ученик сможет в роли кассира или бухгалтера команды вести учёт продаж на ярмарке и посчитать выручку команды по каждому товару и в сумме (целые числа).","criteria":["Я записываю каждую продажу в таблицу.","Я правильно считаю выручку по товарам и общую.","Я сверяю деньги в кассе с записями и нахожу расхождение."],"result":"Таблица учёта продаж команды: количество × цена по каждому товару, общая выручка, сравнение с планом и проверка «касса = записи».","stages":[{"stage":"Разминка «Найди пару»","min":4},{"stage":"Подготовка","min":6},{"stage":"Ярмарка","min":18},{"stage":"Подсчёт","min":7},{"stage":"Рефлексия","min":5}],"warm":{"kind":"match","name":"Найди пару","rules":["На экране определения под номерами.","Учитель называет слово, например: «Слово А — …». 10 секунд на поиск.","Все одновременно показывают номер подходящего определения на пальцах."],"items":[{"term":"Выручка (revenue)","real":"Все деньги, полученные от продажи товаров","shown":"Все деньги, полученные от продажи товаров","truth":true,"first":"В"},{"term":"Ярмарка (fair)","real":"Праздничный рынок на один день","shown":"Проверка, совпадают ли деньги в кассе с записями","truth":false,"first":"Я"},{"term":"Учёт","real":"Записи о каждой продаже: что, сколько, за сколько","shown":"Записи о каждой продаже: что, сколько, за сколько","truth":true,"first":"У"},{"term":"План продаж","real":"Сколько команда собиралась продать и заработать","shown":"Праздничный рынок на один день","truth":false,"first":"П"},{"term":"Касса","real":"Место или коробка, где хранят деньги от продаж","shown":"Место или коробка, где хранят деньги от продаж","truth":true,"first":"К"},{"term":"Сверка","real":"Проверка, совпадают ли деньги в кассе с записями","shown":"Сколько команда собиралась продать и заработать","truth":false,"first":"С"}],"perm":[1,0,5,4,3,2]},"glossary":[{"term":"Выручка (revenue)","def":"Все деньги, полученные от продажи товаров"},{"term":"Ярмарка (fair)","def":"Праздничный рынок на один день"},{"term":"Учёт","def":"Записи о каждой продаже: что, сколько, за сколько"},{"term":"План продаж","def":"Сколько команда собиралась продать и заработать"},{"term":"Касса","def":"Место или коробка, где хранят деньги от продаж"},{"term":"Сверка","def":"Проверка, совпадают ли деньги в кассе с записями"}],"english":"fair — ярмарка; revenue — выручка","concepts":{"head":"Понятия","items":["Выручка (revenue) — все деньги от продаж.","Учёт — записи каждой продажи.","План — цель.","Сверка — касса = записи.","Выручка — ещё не прибыль: из неё потом вычтут расходы (это тема следующего урока)."]},"steps":{"head":"Как считать, по шагам","items":["До ярмарки записать план: товар, цена, сколько хотим продать","Каждую продажу отмечать палочкой в строке товара","После ярмарки выручка по товару = количество × цена","Сложить выручку всех товаров","Посчитать деньги в кассе","Сверка: если не совпадает — искать ошибку (не записали, неверная сдача)","Сравнить с планом: выполнили, перевыполнили или нет"]},"scheme":"Таблица: «Товар | Цена | Продано | Выручка». Строка «Итого». Ниже: «План ___ / Факт ___ / Касса ___ / Расхождение ___».","examples":[{"lab":"Казахстан","text":"Команда «Дала»: закладки 300 тенге × 12 = 3600; брелоки 500 тенге × 8 = 4000; открытки 200 тенге × 15 = 3000. Выручка: 3600 + 4000 + 3000 = 10 600 тенге. План был 10 000 тенге — перевыполнили на 600. В кассе 10 400 — расхождение 200 тенге: забыли записать одну открытку или дали лишнюю сдачу."},{"lab":"Мир","text":"В магазинах по всему миру кассиры в конце смены делают сверку кассы."}],"mistake":{"myth":"Путать выручку и прибыль («мы заработали 10 600»)","fix":"Выручка — все деньги; прибыль — после вычета расходов, её посчитаем на следующем уроке."},"check":[{"q":"Как посчитать выручку по товару?","a":"Количество × цена"},{"q":"500 × 8 = ?","a":"4000"},{"q":"Записи 10 600, в кассе 10 400 — расхождение?","a":"200 тенге"}],"kz":{"text":"В Казахстане магазины выдают покупателям кассовые чеки, в том числе электронные, а данные о продажах передаются через онлайн-кассы.","link":"каждая продажа записывается, чтобы выручка была точной."},"world":{"text":"В магазинах и банках по всему миру кассиры делают сверку кассы в конце каждой смены, а первые кассовые аппараты придумали, чтобы не терять деньги и не путать записи.","link":""},"fact":"Кассовый аппарат изобрёл в 1879 году Джеймс Ритти — владелец салуна в США, чтобы точно учитывать выручку; позже на основе его изобретения выросла компания NCR.","cards":[{"n":"1","title":"План продаж","lines":["Товар 1: ___ цена ___ × план ___ = ___ тенге","Товар 2: ___ цена ___ × план ___ = ___ тенге","Товар 3: ___ цена ___ × план ___ = ___ тенге","План выручки: ___ тенге."],"hand":"Сдать: план.","answers":[]},{"n":"2","title":"Учёт продаж (revenue)","lines":["Товар | Цена | Продано (палочки) | Выручка","___ | ___ | ___ | ___","Итого выручка: ___ тенге."],"hand":"Сдать: таблицу.","answers":[]},{"n":"3","title":"Сверка и задача","lines":["Деньги в кассе: ___ Записи: ___ Расхождение: ___","План: ___ Факт: ___ Выполнили? ___","Задача: закладки 300 × 12, брелоки 500 × 8, открытки 200 × 15. Выручка? (Ответ: 3600 + 4000 + 3000 = 10 600 тенге.) План 10 000 — на сколько перевыполнили? (600.) В кассе 10 400 — расхождение?"],"hand":"Сдать: решение.","answers":[["","200 тенге."]]}],"practice":[{"type":"scene","title":"Касса ярмарки","minutes":7,"setting":"Кассир записывает каждую продажу в таблицу.","roles":[{"name":"Покупатели","task":"Покупаете разные товары."},{"name":"Кассир","task":"Принимаешь деньги."},{"name":"Учётчик","task":"Записываешь каждую продажу."}],"steps":["Покупки.","Запись.","Подсчёт выручки по товарам."],"freeze":["Стоп-кадр! Какой товар принёс больше всего?"],"twist":"Поворот: деньги в кассе и записи не совпадают! Ищем ошибку.","debrief":["Зачем записывать каждую продажу?"]},{"type":"scene","title":"Найди расхождение","minutes":6,"setting":"В кассе на 100 тенге меньше, чем в записях.","roles":[{"name":"Детектив","task":"Сверяешь запись и деньги."},{"name":"Кассир","task":"Вспоминаешь продажи."}],"steps":["Сверка.","Поиск ошибки."],"freeze":["Стоп-кадр! Где ошибка?"],"twist":null,"debrief":["Как не ошибаться в кассе?"]},{"type":"scene","title":"Общая выручка","minutes":5,"setting":"Складываем выручку по всем товарам.","roles":[{"name":"Счетовод","task":"Складываешь."},{"name":"Проверяющий","task":"Проверяешь."}],"steps":["Сложение.","Проверка."],"freeze":["Стоп-кадр! Верно?"],"twist":null,"debrief":["Что такое общая выручка?"]}],"homework":"Сохранить таблицу учёта и выписать отдельно, какие расходы были у команды (материалы, упаковка) — к следующему уроку.","support":"Таблица с готовыми ценами и подсказкой «палочки по 5»; роль помощника кассира.","advanced":"Посчитать, сколько товаров каждого вида нужно было продать ещё, чтобы выручка стала 12 000 тенге.","photo":{"src":"lessons/img/04_28.jpg","author":"Alexander Mils","q":["Что вы видите на фото? Как это связано с нашей темой?","Почему честный учёт важен даже для маленькой ярмарки?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g04-l28.pptx","name":"28. Выручка ярмарки — сколько мы получили (4 кл).pptx","mb":1.6}},{"id":"04_29","g":4,"l":29,"topic":"Расходы и прибыль: что осталось после ярмарки","module":"Коммуникации и продажи","format":"Симуляция, ярмарка","skills":["Финансовое мышление","Принятие решений","Командная работа"],"goal":"К концу урока ученик сможет посчитать расходы команды на ярмарку и прибыль по формуле «прибыль = выручка − расходы» в целых тенге и объяснить, почему выручка не равна прибыли.","criteria":["Я составляю список всех расходов и складываю их.","Я правильно считаю прибыль: выручка минус расходы.","Я предлагаю, как увеличить прибыль, и объясняю решение."],"result":"Финансовый отчёт команды после ярмарки: список расходов, выручка, прибыль (или убыток) и одно решение, как увеличить прибыль, проверенное на мини-ярмарке.","stages":[{"stage":"Разминка «Правда или ловушка?»","min":4},{"stage":"Подготовка","min":6},{"stage":"Ярмарка","min":18},{"stage":"Подсчёт","min":7},{"stage":"Рефлексия","min":5}],"warm":{"kind":"truth","name":"Правда или ловушка?","rules":["Учитель читает слово урока и объяснение — правильное или «перепутанное».","10 секунд молча решаем, так ли объясняется слово.","«Три-два-один!» — все сразу показывают: ладонь вверх = ПРАВДА, кулак = ЛОВУШКА."],"items":[{"term":"Прибыль (profit)","real":"Деньги, которые остались после того, как из выручки вычли все расходы","shown":"Деньги, которые остались после того, как из выручки вычли все расходы","truth":true,"first":"П"},{"term":"Ярмарка (fair)","real":"Праздничный рынок на один день","shown":"Таблица с выручкой, расходами и прибылью","truth":false,"first":"Я"},{"term":"Выручка","real":"Все деньги от продаж","shown":"Все деньги от продаж","truth":true,"first":"В"},{"term":"Расходы","real":"Деньги, потраченные на материалы, упаковку, место, рекламу","shown":"Праздничный рынок на один день","truth":false,"first":"Р"},{"term":"Убыток","real":"Когда расходы больше выручки","shown":"Когда расходы больше выручки","truth":true,"first":"У"},{"term":"Финансовый отчёт","real":"Таблица с выручкой, расходами и прибылью","shown":"Деньги, потраченные на материалы, упаковку, место, рекламу","truth":false,"first":"Ф"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Прибыль (profit)","def":"Деньги, которые остались после того, как из выручки вычли все расходы"},{"term":"Ярмарка (fair)","def":"Праздничный рынок на один день"},{"term":"Выручка","def":"Все деньги от продаж"},{"term":"Расходы","def":"Деньги, потраченные на материалы, упаковку, место, рекламу"},{"term":"Убыток","def":"Когда расходы больше выручки"},{"term":"Финансовый отчёт","def":"Таблица с выручкой, расходами и прибылью"}],"english":"fair — ярмарка; profit — прибыль","concepts":{"head":"Понятия","items":["Выручка — все деньги от продаж.","Расходы — что потратили.","Прибыль (profit) = выручка − расходы.","Убыток — если расходы больше выручки.","Финансовый отчёт — таблица с этими цифрами."]},"steps":{"head":"Как посчитать, по шагам","items":["Выписать все расходы: материалы, упаковка, листовки, место на ярмарке","Сложить их","Взять выручку из таблицы учёта","Вычесть расходы из выручки","Если получилось меньше нуля — это убыток","Найти, как увеличить прибыль: уменьшить расходы (дешевле материалы, меньше упаковки), увеличить продажи (лучше реклама, ответы на возражения) или пересмотреть цену"]},"scheme":"Большой прямоугольник «Выручка 10 600», внутри него часть «Расходы 7600» и часть «Прибыль 3000». Рядом три стрелки «Как увеличить прибыль»: меньше расходов, больше продаж, правильная цена.","examples":[{"lab":"Казахстан","text":"Команда «Дала»: выручка 10 600 тенге. Расходы: материалы 4200, упаковка 1100, листовки 800, место 1500 — всего 7600 тенге. Прибыль: 10 600 − 7600 = 3000 тенге. Команда «Тулпар»: выручка 6000, расходы 6800 — убыток 800 тенге, потому что купили дорогую упаковку."},{"lab":"Мир","text":"У любой компании в мире — от маленького кафе до большой фабрики — главный вопрос «сколько осталось после расходов?»."}],"mistake":{"myth":"Забывают часть расходов (место, листовки), и прибыль получается «больше, чем есть»","fix":"Пройти по списку «материалы — упаковка — реклама — место» и проверить каждую строку."},"check":[{"q":"Чем выручка отличается от прибыли?","a":"Прибыль — после вычета расходов"},{"q":"Выручка 8000, расходы 5500 — прибыль?","a":"2500 тенге"},{"q":"Выручка 6000, расходы 6800 — что это?","a":"Убыток 800 тенге"}],"kz":{"text":"Казахстанские фермеры на ярмарках выходного дня считают не только выручку, но и расходы на корм, транспорт и место.","link":"фермер решает, выгодно ли ехать на ярмарку, только посчитав прибыль."},"world":{"text":"Многие социальные предприятия в мире направляют часть прибыли на решение проблем общества: обучение детей, защиту природы. Например, есть компании, которые за каждую проданную пару обуви помогают нуждающимся.","link":""},"fact":"Двойную бухгалтерскую запись, по которой до сих пор учитывают доходы и расходы, описал итальянский математик Лука Пачоли в книге 1494 года.","cards":[{"n":"1","title":"Наши расходы","lines":["Материалы: ___ тенге. Упаковка: ___ тенге. Листовки: ___ тенге. Место на ярмарке: ___ тенге. Другое: ___","Всего расходов: ___ тенге.","Выручка (из таблицы учёта): ___ тенге."],"hand":"Сдать: список.","answers":[]},{"n":"2","title":"Финансовый отчёт","lines":["Прибыль (profit) = выручка ___ − расходы ___ = ___ тенге.","Прибыль или убыток? ___","Как увеличить прибыль: меньше расходов / больше продаж / другая цена. Наше решение: ___"],"hand":"Сдать: отчёт.","answers":[]},{"n":"3","title":"Задачи","lines":["1) Выручка 10 600, расходы 4200 + 1100 + 800 + 1500. Прибыль?","2) Выручка 6000, расходы 6800. Что получилось?","3) Фермер: выручка 50 000, расходы 12 000. Прибыль?"],"hand":"Сдать: решения.","answers":[["1","10 600 − 7600 = 3000 тенге."],["2","Убыток 800 тенге."],["3","38 000 тенге."]]}],"practice":[{"type":"scene","title":"Куда ушли деньги?","minutes":7,"setting":"После ярмарки команда считает расходы: материалы, упаковка, вывеска.","roles":[{"name":"Капитан","task":"Называешь выручку."},{"name":"Бухгалтер","task":"Перечисляешь расходы и складываешь."},{"name":"Аналитик","task":"Считаешь прибыль: выручка минус расходы."}],"steps":["Выручка.","Расходы.","Прибыль."],"freeze":["Стоп-кадр! Получилась ли прибыль?"],"twist":"Поворот: оказалось, забыли посчитать скотч и краски. Что стало с прибылью?","debrief":["Чем выручка отличается от прибыли?"]},{"type":"scene","title":"Как увеличить прибыль","minutes":6,"setting":"Команда предлагает способы получить больше прибыли.","roles":[{"name":"Идея 1","task":"Предлагаешь продать больше."},{"name":"Идея 2","task":"Предлагаешь потратить меньше."},{"name":"Капитан","task":"Выбираешь лучшую идею."}],"steps":["Идеи.","Выбор."],"freeze":["Стоп-кадр! Какая идея реальнее?"],"twist":null,"debrief":["Как можно увеличить прибыль?"]},{"type":"scene","title":"Убыток","minutes":5,"setting":"Одна команда потратила больше, чем заработала.","roles":[{"name":"Капитан команды с убытком","task":"Рассказываешь, что пошло не так."},{"name":"Советник","task":"Подсказываешь, что изменить."}],"steps":["Рассказ.","Совет."],"freeze":["Стоп-кадр! Почему получился убыток?"],"twist":null,"debrief":["Что такое убыток и как его избежать?"]}],"homework":"Посчитать с родителями «прибыль» одного домашнего дела, например выпечки на продажу: выручка минус расходы на продукты (условные цифры).","support":"Отчёт с готовыми строками расходов и задача с круглыми числами.","advanced":"Посчитать, сколько товаров по 500 тенге команде «Тулпар» нужно было продать ещё, чтобы выйти без убытка (ответ: 2 — это 1000 тенге, больше 800).","photo":{"src":"lessons/img/04_29.jpg","author":"Numbers On Your Tip","q":["Что вы видите на фото? Как это связано с нашей темой?","На что команда могла бы направить часть прибыли, чтобы помочь другим?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g04-l29.pptx","name":"29. Расходы и прибыль — что осталось после ярмарки (4 кл).pptx","mb":1.5}},{"id":"04_30","g":4,"l":30,"topic":"Итоговая работа за полугодие (Тестирование. Итоговое занятие)","module":"Коммуникации и продажи","format":"Итоговая работа","skills":["Критическое мышление","Финансовое мышление"],"goal":"К концу урока ученик сможет самостоятельно выполнить итоговую работу: ответить на 12 вопросов теста по терминам модуля «Коммуникации и продажи» и решить практическое задание — портрет клиента, ответ на возражение и расчёт прибыли.","criteria":["Я отвечаю на вопросы теста самостоятельно.","Я пишу ответ на возражение по схеме и описываю клиента.","Я правильно считаю выручку и прибыль и проверяю себя по ключу."],"result":"Выполненная итоговая работа: тест из 12 вопросов и практическое задание из 3 частей, проверенные по ключу самопроверки.","stages":[{"stage":"Разминка «Угадай слово»","min":4},{"stage":"Выполнение работы","min":28},{"stage":"Самопроверка","min":4},{"stage":"Рефлексия","min":4}],"warm":{"kind":"guess","name":"Угадай слово","rules":["Слово спрятано — звучит только его объяснение и первая буква.","10 секунд команда шёпотом выбирает одно слово.","«Три-два-один!» — все команды хором называют слово. Верно — балл команде."],"items":[{"term":"Тестирование (testing)","real":"Проверка знаний с помощью вопросов и заданий","shown":"Проверка знаний с помощью вопросов и заданий","truth":true,"first":"Т"},{"term":"Повторение (review)","real":"Когда вспоминаем изученное","shown":"Всё, откуда люди получают информацию: интернет, ТВ, реклама, разговоры","truth":false,"first":"П"},{"term":"Информация","real":"Сведения о чём-либо: о товаре, цене, покупателе","shown":"Сведения о чём-либо: о товаре, цене, покупателе","truth":true,"first":"И"},{"term":"Коммуникация","real":"Обмен информацией между людьми","shown":"Когда вспоминаем изученное","truth":false,"first":"К"},{"term":"Сообщение","real":"То, что один человек передаёт другому: слова, текст, знак","shown":"То, что один человек передаёт другому: слова, текст, знак","truth":true,"first":"С"},{"term":"Информационное пространство","real":"Всё, откуда люди получают информацию: интернет, ТВ, реклама, разговоры","shown":"Обмен информацией между людьми","truth":false,"first":"И"}],"perm":[3,2,1,0,5,4]},"glossary":[{"term":"Тестирование (testing)","def":"Проверка знаний с помощью вопросов и заданий"},{"term":"Повторение (review)","def":"Когда вспоминаем изученное"},{"term":"Информация","def":"Сведения о чём-либо: о товаре, цене, покупателе"},{"term":"Коммуникация","def":"Обмен информацией между людьми"},{"term":"Сообщение","def":"То, что один человек передаёт другому: слова, текст, знак"},{"term":"Информационное пространство","def":"Всё, откуда люди получают информацию: интернет, ТВ, реклама, разговоры"}],"english":"testing — тестирование; review — повторение","concepts":{"head":"Определения","items":["Коммуникация — обмен информацией; сообщение — то, что передают; информационное пространство — интернет, ТВ, реклама.","Клиент и целевая аудитория (5 признаков: возраст, место, интересы, потребность, бюджет).","Честная цена = себестоимость + расходы на продажу + прибыль, без скрытых платежей.","Права покупателя: информация, качество, обмен и возврат (нужен чек).","Виды продаж: магазин, онлайн, ярмарка.","5 этапов продажи: контакт, вопросы, предложение, сомнения, завершение.","Возражение: согласиться — уточнить — аргумент.","Выручка = количество × цена; прибыль = выручка − расходы."]},"steps":{"head":"Как выполнять работу, по шагам","items":["Прочитай вопрос","Выбери один ответ","В практике пиши полные решения","Трудное — пропусти и вернись","Проверь по ключу"]},"scheme":"Карта модуля: «Клиент → Цена → Права → Виды продаж → Этапы → Возражения → Выручка и прибыль».","examples":[{"lab":"Казахстан","text":"Брелок 1500 тенге × 6 = 9000 тенге выручки; расходы 5400 — прибыль 3600 тенге. Ответ на «дорого»: «Понимаю. Для чего вам? Он прослужит весь год»."},{"lab":"Мир","text":"Всемирный день прав потребителей — 15 марта."}],"mistake":{"myth":"Путают выручку и прибыль","fix":"Прибыль всегда после вычитания расходов."},"check":[{"q":"Первый этап продажи?","a":"Контакт"},{"q":"Зачем хранить чек?","a":"Для обмена и возврата"},{"q":"9000 − 5400 = ?","a":"3600"}],"kz":{"text":"Казахстан участвует в исследовании PISA, в том числе в блоке финансовой грамотности, где школьники решают задачи о покупках, ценах и правах потребителя.","link":"итоговая работа — тренировка таких умений."},"world":{"text":"Во многих странах школьники проходят итоговые проверки по финансовой грамотности, а исследование PISA ОЭСР проверяет, умеют ли 15-летние подростки разных стран принимать решения о деньгах.","link":""},"fact":"Блок финансовой грамотности впервые включили в исследование PISA в 2012 году; в нём школьники решают задачи о бюджетах, ценах и рисках.","cards":[{"n":"1","title":"Тест (обведи один ответ)","lines":["1. Коммуникация — это: а) обмен информацией между людьми; б) покупка товара.","2. Целевая аудитория — это: а) люди, для которых сделан товар; б) все жители города.","3. Честная цена: а) понятна и без скрытых платежей; б) всегда самая низкая.","4. Чек нужен, чтобы: а) подтвердить покупку и вернуть товар; б) украсить пакет.","5. Право покупателя: а) на информацию о товаре; б) брать товар бесплатно.","6. Онлайн-продажа: а) через сайт или приложение; б) только на ярмарке.","7. Первый этап продажи: а) контакт и приветствие; б) чек.","8. Вопросы продавца нужны, чтобы: а) понять потребность; б) задержать покупателя.","9. Ответ на возражение начинается с: а) «Понимаю вас»; б) «Вы не правы».","10. Нечестный приём: а) запугивать покупателя; б) задавать вопросы.","11. Выручка — это: а) все деньги от продаж; б) деньги после расходов.","12. Прибыль = а) выручка − расходы; б) выручка + расходы."],"hand":"Сдать: тест.","answers":[]},{"n":"2","title":"Практическое задание","lines":["1) Опиши клиента для товара «бутылка для воды с часами-напоминанием» по 5 признакам.","2) Клиент говорит: «Дорого — 2500 тенге». Напиши ответ по схеме «согласиться — уточнить — аргумент».","3) Продали 6 бутылок по 2500 тенге.","Расходы: материалы 7000, реклама 1500, место 1000. Посчитай выручку и прибыль."],"hand":"Сдать: решение.","answers":[]},{"n":"3","title":"Ключ","lines":["Тест: все ответы «а» (1–12), по 1 баллу — 12 баллов.","Практика: 1) все 5 признаков — 2 балла; 2) три части ответа — 2 балла; 3) выручка 6 × 2500 = 15 000; расходы 9500; прибыль 5500 тенге — 2 балла.","Всего 18 баллов. Перевод: 17–18 → 10; 15–16 → 9; 13–14 → 8; 11–12 → 7; 9–10 → 6; 7–8 → 5; меньше 7 — 4 и ниже."],"hand":"Сдать: работу с баллами.","answers":[]}],"homework":"Не задаётся; по желанию — рассказать родителям о самой полезной теме полугодия.","support":"Тест с крупным шрифтом и чтением вопросов вслух; в практике — шаблон ответа на возражение.","advanced":"Дополнительное задание: составить короткое предложение товара (5 окошек) для клиента из практического задания.","photo":{"src":"lessons/img/04_30.jpg","author":"Vitaly Gariev","q":["Что вы видите на фото? Как это связано с нашей темой?","Какие умения из нашего модуля пригодятся вам в любой стране?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g04-l30.pptx","name":"30. Итоговая работа за полугодие (Тестирование. Итоговое занятие) (4 кл).pptx","mb":1.4}},{"id":"04_31","g":4,"l":31,"topic":"Работа над ошибками и обратная связь по итоговой работе","module":"Коммуникации и продажи","format":"Итоговая работа","skills":["Критическое мышление","Финансовое мышление"],"goal":"К концу урока ученик сможет найти и исправить свои ошибки в итоговой работе с объяснением правила и решить по одному похожему заданию на каждую тему, где ошибся.","criteria":["Я нахожу и исправляю свои ошибки.","Я объясняю правило, по которому исправил.","Я решаю похожие задания и принимаю обратную связь тренера."],"result":"Лист работы над ошибками с исправлениями «Правильно так, потому что…» и решёнными похожими заданиями; личный план повторения из 1–2 тем.","stages":[{"stage":"Разминка «Найди пару»","min":4},{"stage":"Выполнение работы","min":28},{"stage":"Самопроверка","min":4},{"stage":"Рефлексия","min":4}],"warm":{"kind":"match","name":"Найди пару","rules":["На экране определения под номерами.","Учитель называет слово, например: «Слово А — …». 10 секунд на поиск.","Все одновременно показывают номер подходящего определения на пальцах."],"items":[{"term":"Ошибка (mistake)","real":"Неправильный ответ, который показывает, что нужно повторить","shown":"Неправильный ответ, который показывает, что нужно повторить","truth":true,"first":"О"},{"term":"Обратная связь (feedback)","real":"Подсказка, что получилось и что улучшить","shown":"Сомнение покупателя","truth":false,"first":"О"},{"term":"Исправление","real":"Правильный ответ с объяснением","shown":"Правильный ответ с объяснением","truth":true,"first":"И"},{"term":"Выручка","real":"Все деньги от продаж","shown":"Подсказка, что получилось и что улучшить","truth":false,"first":"В"},{"term":"Прибыль","real":"Выручка минус расходы","shown":"Выручка минус расходы","truth":true,"first":"П"},{"term":"Возражение","real":"Сомнение покупателя","shown":"Все деньги от продаж","truth":false,"first":"В"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Ошибка (mistake)","def":"Неправильный ответ, который показывает, что нужно повторить"},{"term":"Обратная связь (feedback)","def":"Подсказка, что получилось и что улучшить"},{"term":"Исправление","def":"Правильный ответ с объяснением"},{"term":"Выручка","def":"Все деньги от продаж"},{"term":"Прибыль","def":"Выручка минус расходы"},{"term":"Возражение","def":"Сомнение покупателя"}],"english":"mistake — ошибка; feedback — обратная связь","concepts":{"head":"Понятия","items":["Ошибка (mistake) — подсказка, что повторить.","Обратная связь (feedback) — что получилось и что улучшить.","Работа над ошибками: найти → понять правило → исправить → потренироваться."]},"steps":{"head":"Как работать, по шагам","items":["Найди задание с отметкой","Перечитай вопрос","Найди правило в «памятке модуля»","Запиши правильный ответ","Объясни «потому что»","Реши похожее задание","Запиши 1–2 темы в личный план повторения"]},"scheme":"«Памятка модуля»: 5 признаков ЦА; честная цена = себестоимость + расходы + прибыль; 3 права покупателя; 5 этапов продажи; возражение: согласиться — уточнить — аргумент; выручка = количество × цена; прибыль = выручка − расходы.","examples":[{"lab":"Казахстан","text":"Ученик написал: «Выручка 15 000, расходы 9500, прибыль 24 500». Ошибка: сложил. Правильно: 15 000 − 9500 = 5500 тенге. Ответ на возражение «Нет, у нас не дорого!» — ошибка: спор. Правильно: «Понимаю вас. Для чего вам бутылка? Она напоминает пить воду, и не нужно покупать воду в школе». Портрет клиента «все люди» — ошибка: нужно 5 признаков."},{"lab":"Мир","text":"В компаниях многих стран после каждого проекта проводят разбор «что получилось, что улучшить»."}],"mistake":{"myth":"Исправить, не поняв правило","fix":"Обязательное «потому что» и похожее задание без подсказки."},"check":[{"q":"Выручка 8000, расходы 5000 — прибыль?","a":"3000"},{"q":"С чего начинаем ответ на возражение?","a":"«Понимаю вас»"},{"q":"Сколько признаков у портрета клиента?","a":"5"}],"kz":{"text":"Казахстанские спортсмены и шахматисты разбирают каждую партию и бой с тренером. Шахматистка Бибисара Асаубаева, чемпионка мира по блицу, анализирует свои ошибки после каждого турнира.","link":"разбор ошибок — путь к победе."},"world":{"text":"Во многих компаниях мира после проекта проводят разбор: что сработало, что нет и что сделать иначе; в армии и медицине такой разбор помогает не повторять ошибок.","link":""},"fact":"Метод разбора «After Action Review» (разбор после действия) разработали в армии США в 1970-е годы, а затем его стали использовать компании по всему миру.","cards":[{"n":"1","title":"Работа над ошибками","lines":["Номер задания: ___ Мой","Правило: ___","Правильно так, потому что: ___","Мой план повторения: 1) ___ 2) ___"],"hand":"Сдать: лист.","answers":[["","___ Правильный ответ: ___"]]},{"n":"2","title":"Похожие задания","lines":["1. Выручка 12 000, расходы 7500. Прибыль?","2. Продали 7 брелоков по 600 тенге. Выручка?","3. Исправь ответ на возражение: «Да не дорого это!» (Пример: «Понимаю вас. Скажите, для чего вам? Он прослужит весь год».)","4. Что нужно, чтобы вернуть товар с браком?","5. Назови 5 этапов продажи. (Контакт, вопросы, предложение, сомнения, завершение.)"],"hand":"Сдать: ответы.","answers":[["","4500 тенге."],["","4200 тенге."],["","Чек и сам товар."]]},{"n":"3","title":"Ключ для взаимопроверки","lines":["Ответы Карточки 2: 4500; 4200; ответ начинается с согласия, есть вопрос и аргумент; чек и товар; контакт — вопросы — предложение — сомнения — завершение.","Проверь: у каждого исправления есть «потому что»."],"hand":"Сдать: подпись проверяющего.","answers":[]}],"homework":"Повторить 1–2 темы из личного плана и решить задачу: продали 9 закладок по 400 тенге, расходы 2100 — прибыль? (Ответ: 3600 − 2100 = 1500 тенге.)","support":"Памятка на парте и задания с готовым началом решения; работа с тренером.","advanced":"Составить для одноклассника задачу на прибыль и задание «исправь ответ на возражение» с ключом.","photo":{"src":"lessons/img/04_31.jpg","author":"lilartsy","q":["Что вы видите на фото? Как это связано с нашей темой?","Какую свою ошибку за полугодие вы превратили в умение?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g04-l31.pptx","name":"31. Работа над ошибками и обратная связь по итоговой работе (4 кл).pptx","mb":1.5}},{"id":"04_32","g":4,"l":32,"topic":"Игра-повторение по темам полугодия","module":"Коммуникации и продажи","format":"Деловая игра","skills":["Командная работа","Финансовое мышление","Работа с клиентом"],"goal":"К концу урока ученик сможет в командной игре «Торговый центр» применить понятия полугодия — целевая аудитория, честная цена, права покупателя, этапы продажи, возражения, выручка и прибыль — и закрепить темы, где были ошибки.","criteria":["Я правильно применяю понятия полугодия в ответах.","Я считаю выручку и прибыль без ошибок.","Я помогаю команде и играю честно."],"result":"Табло команды за 2 раунда и «финансовый отчёт магазина» из раунда 2: продажи, выручка, расходы, прибыль в целых тенге.","stages":[{"stage":"Разминка «Правда или ловушка?»","min":4},{"stage":"Инструктаж","min":4},{"stage":"Раунд 1","min":10},{"stage":"Раунд 2","min":10},{"stage":"Разбор","min":8},{"stage":"Рефлексия","min":4}],"warm":{"kind":"truth","name":"Правда или ловушка?","rules":["Учитель читает слово урока и объяснение — правильное или «перепутанное».","10 секунд молча решаем, так ли объясняется слово.","«Три-два-один!» — все сразу показывают: ладонь вверх = ПРАВДА, кулак = ЛОВУШКА."],"items":[{"term":"Повторение (review)","real":"Когда вспоминаем изученное","shown":"Когда вспоминаем изученное","truth":true,"first":"П"},{"term":"Игра (game)","real":"Занятие по правилам","shown":"Выручка минус расходы","truth":false,"first":"И"},{"term":"Целевая аудитория","real":"Люди, для которых сделан товар","shown":"Люди, для которых сделан товар","truth":true,"first":"Ц"},{"term":"Возражение","real":"Сомнение покупателя","shown":"Занятие по правилам","truth":false,"first":"В"},{"term":"Выручка","real":"Все деньги от продаж","shown":"Все деньги от продаж","truth":true,"first":"В"},{"term":"Прибыль","real":"Выручка минус расходы","shown":"Сомнение покупателя","truth":false,"first":"П"}],"perm":[1,0,5,4,3,2]},"glossary":[{"term":"Повторение (review)","def":"Когда вспоминаем изученное"},{"term":"Игра (game)","def":"Занятие по правилам"},{"term":"Целевая аудитория","def":"Люди, для которых сделан товар"},{"term":"Возражение","def":"Сомнение покупателя"},{"term":"Выручка","def":"Все деньги от продаж"},{"term":"Прибыль","def":"Выручка минус расходы"},{"term":"Права покупателя","def":"Информация, качество, обмен и возврат"}],"english":"review — повторение; game — игра","concepts":{"head":"Понятия полугодия","items":["Целевая аудитория — 5 признаков.","Честная цена — понятна, без скрытых платежей.","Права покупателя — информация, качество, обмен и возврат (чек).","Виды продаж — магазин, онлайн, ярмарка.","5 этапов продажи.","Возражения — согласиться, уточнить, аргумент.","Выручка = количество × цена.","Прибыль = выручка − расходы."]},"scheme":"Табло 5 × 3: отделы × 1, 2, 3 балла. Справа бланк «День магазина»: выручка — расходы — прибыль — возражение — жалоба.","examples":[{"lab":"Казахстан","text":"Магазин «Термос»: продали 9 термосов по 4500 тенге = 40 500 тенге; расходы 27 000 тенге; прибыль 13 500 тенге. Возражение «у соседей дешевле» — ответ: «Понимаю. Давайте сравним: у нашего термоса гарантия 1 год и он держит тепло 12 часов». Жалоба: термос протекает, чек есть — замена или возврат."},{"lab":"Мир","text":"В торговых центрах многих стран отделы соревнуются за звание «лучший сервис месяца»."}],"mistake":{"myth":"Команды спешат и путают выручку и прибыль","fix":"Правило «сначала выручка, потом вычитаем расходы, потом проверяем»."},"check":[{"q":"9 × 4500 = ?","a":"40 500"},{"q":"40 500 − 27 000 = ?","a":"13 500"},{"q":"Покупатель с браком и чеком — что можно?","a":"Замену, ремонт или возврат денег"}],"kz":{"text":"Торговые центры Казахстана, например «Хан Шатыр» в Астане, объединяют десятки магазинов, кафе и развлечений под одной крышей.","link":"в каждом магазине работают те же правила — клиент, честная цена, права покупателя, продажи, прибыль."},"world":{"text":"В больших торговых центрах мира работают сотни магазинов, и каждый борется за покупателя честным сервисом и понятными ценами. Покупатели по всему миру оставляют отзывы, и магазины с хорошим обслуживанием выигрывают.","link":""},"fact":"Торгово-развлекательный центр «Хан Шатыр» в Астане построен в форме огромного шатра по проекту британского архитектора Нормана Фостера и открыт в 2010 году.","cards":[{"n":"1","title":"Правила «Торгового центра»","lines":["Роли: капитан, бухгалтер, продавец, юрист (права покупателя).","Раунд 1: выбирай отдел и вопрос за 1, 2 или 3 балла; 20 секунд на совет.","Раунд 2: «День магазина» — отчёт, ответ на возражение, решение жалобы. Жюри: верный расчёт — 3 балла, ответ на возражение — 2, решение жалобы — 2."],"hand":"Сдать: табло.","answers":[]},{"n":"2","title":"Вопросы отделов (для тренера)","lines":["Клиент (1): назовите 5 признаков ЦА. — Возраст, место, интересы, потребность, бюджет.","Цена (2): что делает цену нечестной? — Скрытые платежи, ложная скидка, разная цена.","Права (2): 3 права покупателя? — Информация, качество, обмен и возврат.","Продажа (1): первый этап продажи? — Контакт.","Продажа (3): 3 вида вопросов продавца? — О ситуации, о проблеме, о пользе.","Возражения (3): ответьте на «я подумаю». — «Конечно! Что поможет решить…?»"],"hand":"Сдать: отметки баллов.","answers":[]},{"n":"3","title":"«День магазина» (ситуации)","lines":["А. Термосы: 9 шт. по 4500; расходы 27 000. Возражение: «У соседей дешевле». Жалоба: протекает, чек есть. (Выручка 40 500, прибыль 13 500; замена или возврат.)","Б. Рюкзаки: 6 шт. по 9500; расходы 41 000. Возражение: «Я подумаю». Жалоба: не подошёл цвет, 5 дней, ярлыки и чек есть. (Выручка 57 000, прибыль 16 000; обмен.)","В. Настольные игры: 8 шт. по 6000; расходы 30 000. Возражение: «Дорого». Жалоба: нет одной фишки. (Выручка 48 000, прибыль 18 000; брак — замена.)","Г. Брелоки: 20 шт. по 1500; расходы 21 000. Возражение: «Мне не нужно». Жалоба: на ценнике 1500, пробили 1700. (Выручка 30 000, прибыль 9000; вернуть 200 тенге, извиниться.)"],"hand":"Сдать: отчёт и ответы.","answers":[]}],"practice":[{"type":"scene","title":"Продавец года","minutes":6,"setting":"Игра: команды по очереди разыгрывают мини-продажу по всем этапам.","roles":[{"name":"Продавец команды","task":"Продаёшь по 5 этапам."},{"name":"Покупатель-соперник","task":"Возражаешь."},{"name":"Жюри","task":"Даёшь баллы за этапы."}],"steps":["Продажа.","Возражение.","Оценка."],"freeze":["Стоп-кадр! Все ли этапы прошли?"],"twist":null,"debrief":["Что мы умеем в продажах?"]},{"type":"scene","title":"Счётная эстафета","minutes":5,"setting":"Команды считают выручку и прибыль на скорость.","roles":[{"name":"Ведущий","task":"Даёшь задачу."},{"name":"Команды","task":"Считаете и поднимаете руку."}],"steps":["Задача.","Решение.","Проверка."],"freeze":["Стоп-кадр! Как посчитали прибыль?"],"twist":null,"debrief":["Как считать выручку и прибыль?"]}],"homework":"Придумать свою ситуацию «День магазина» (товар, цена, продажи, расходы) и посчитать выручку и прибыль.","support":"Шпаргалка формул для команды и вопросы за 1 балл.","advanced":"Ответить на «вопрос со звёздочкой»: как изменится прибыль магазина «Термос», если расходы вырастут на 3000 тенге? (Ответ: 10 500 тенге.)","photo":{"src":"lessons/img/04_32.jpg","author":"National Cancer Institute","q":["Что вы видите на фото? Как это связано с нашей темой?","Что сделало бы наш «Торговый центр» лучшим в мире?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g04-l32.pptx","name":"32. Игра-повторение по темам полугодия (4 кл).pptx","mb":1.5}}];
